fn restore_native_window_state(
    workspace: Option<&Workspace>,
    id: &str,
    previous_epoch: u64,
) -> NativeWindowState {
    let snapshot = workspace.and_then(|workspace| project_window_snapshot(workspace, id));
    let bounds = snapshot.and_then(|window| window.bounds.clone());
    NativeWindowState {
        channel_bus: None,
        open: snapshot.is_some_and(|window| window.open),
        bounds: bounds.clone(),
        restore_bounds: bounds,
        epoch: previous_epoch.wrapping_add(1),
        viewport_live: false,
        focus_requested: false,
        focused: false,
        window_level: None,
        level_settle: 0,
        popup_active: false,
    }
}

fn audio_sample_rate_choices(configs: &[AudioOutputConfig]) -> Vec<u32> {
    let common_rates = [
        22_050, 32_000, 44_100, 48_000, 88_200, 96_000, 176_400, 192_000,
    ];
    let mut rates = Vec::new();
    for config in configs {
        if !config.sample_format_supported_by_engine() {
            continue;
        }
        rates.extend(
            common_rates
                .into_iter()
                .filter(|rate| (config.min_sample_rate..=config.max_sample_rate).contains(rate)),
        );
        rates.push(config.min_sample_rate);
        rates.push(config.max_sample_rate);
    }
    rates.sort_unstable();
    rates.dedup();
    rates
}

fn audio_buffer_choices(configs: &[AudioOutputConfig], sample_rate: Option<u32>) -> Vec<u32> {
    let presets = [64, 128, 256, 512, 1_024, 2_048, 4_096];
    let configured_rate =
        sample_rate.or_else(|| configs.first().map(|config| config.default_sample_rate));
    let matching = configs
        .iter()
        .filter(|config| {
            config.sample_format_supported_by_engine()
                && configured_rate.is_some_and(|rate| {
                    (config.min_sample_rate..=config.max_sample_rate).contains(&rate)
                })
        })
        .collect::<Vec<_>>();
    let best = matching
        .iter()
        .map(|config| {
            (
                config.sample_format != config.default_sample_format,
                config.channels != config.default_channels,
                config.channels,
            )
        })
        .min();
    let mut buffers = matching
        .into_iter()
        .filter(|config| {
            Some((
                config.sample_format != config.default_sample_format,
                config.channels != config.default_channels,
                config.channels,
            )) == best
        })
        .flat_map(|config| {
            presets.into_iter().filter(move |frames| {
                config
                    .min_buffer_frames
                    .zip(config.max_buffer_frames)
                    .is_some_and(|(min, max)| *frames >= min && *frames <= max)
            })
        })
        .collect::<Vec<_>>();
    buffers.sort_unstable();
    buffers.dedup();
    buffers
}

fn reset_native_window_state(previous_epoch: u64) -> NativeWindowState {
    NativeWindowState {
        epoch: previous_epoch.wrapping_add(1),
        ..Default::default()
    }
}

fn restore_project_window_state(
    workspace: Option<&Workspace>,
    previous_epoch: u64,
) -> ProjectWindowState {
    let snapshot =
        workspace.and_then(|workspace| project_window_snapshot(workspace, PROJECT_WINDOW_ID));
    if let Some(snapshot) = snapshot {
        ProjectWindowState {
            open: snapshot.open,
            bounds: snapshot.bounds.clone(),
            restore_bounds: snapshot.restore_bounds.clone(),
            minimized: false,
            maximized: false,
            z_order: snapshot.z_order,
            epoch: previous_epoch.wrapping_add(1),
            focus_requested: false,
        }
    } else {
        ProjectWindowState {
            open: true,
            epoch: previous_epoch.wrapping_add(1),
            ..Default::default()
        }
    }
}

fn native_window_bounds(ctx: &egui::Context) -> Option<WindowBounds> {
    ctx.input(|input| {
        let viewport = input.viewport();
        if viewport.minimized.unwrap_or(false) {
            return None;
        }
        let outer = viewport.outer_rect?;
        let inner = viewport.inner_rect;
        Some(WindowBounds {
            left: f64::from(outer.left()),
            top: f64::from(outer.top()),
            width: f64::from(outer.width()),
            height: f64::from(outer.height()),
            inner_width: inner.map(|rect| f64::from(rect.width())),
            inner_height: inner.map(|rect| f64::from(rect.height())),
            monitor_id: None,
        })
    })
}

fn app_has_focused_viewport(ctx: &egui::Context) -> bool {
    ctx.input(|input| {
        input
            .raw
            .viewports
            .values()
            .any(|viewport| viewport.focused == Some(true))
    })
}

fn app_scoped_window_level(
    pinned: bool,
    app_focused: bool,
    blocked: bool,
) -> egui::viewport::WindowLevel {
    if pinned && app_focused && !blocked {
        egui::viewport::WindowLevel::AlwaysOnTop
    } else {
        egui::viewport::WindowLevel::Normal
    }
}

#[derive(Default)]
struct SavePromptVisibility {
    active: bool,
    hidden: HashSet<egui::ViewportId>,
}

impl SavePromptVisibility {
    fn sync(&mut self, ctx: &egui::Context, active: bool) -> bool {
        let changed = active != self.active;
        let present = ctx.input(|input| input.raw.viewports.keys().copied().collect());
        let (entered, commands) = self.update(active, &present);
        for (id, visible) in commands {
            ctx.send_viewport_cmd_to(id, egui::ViewportCommand::Visible(visible));
        }
        if entered {
            ctx.send_viewport_cmd_to(egui::ViewportId::ROOT, egui::ViewportCommand::Focus);
        }
        if active {
            ctx.request_repaint_after(std::time::Duration::from_millis(16));
        }
        changed
    }

    fn update(
        &mut self,
        active: bool,
        present: &HashSet<egui::ViewportId>,
    ) -> (bool, Vec<(egui::ViewportId, bool)>) {
        let entered = active && !self.active;
        self.active = active;
        let commands = if active {
            self.hidden.extend(
                present
                    .iter()
                    .copied()
                    .filter(|id| *id != egui::ViewportId::ROOT),
            );
            self.hidden.iter().map(|id| (*id, false)).collect()
        } else {
            self.hidden
                .drain()
                .filter(|id| present.contains(id))
                .map(|id| (id, true))
                .collect()
        };
        (entered, commands)
    }
}

fn channel_window_level(
    pinned: bool,
    owner_focused: bool,
    dialog_open: bool,
) -> egui::viewport::WindowLevel {
    // Windows uses ordinary HWND ownership in native_windows.rs so Channel
    // Settings stays above Project without becoming globally topmost.
    #[cfg(windows)]
    {
        let _ = (pinned, owner_focused, dialog_open);
        egui::viewport::WindowLevel::Normal
    }
    // Other desktop systems lack owner-relative ordering. Keep the fallback
    // app-scoped as far as the platform allows and release it for dialogs.
    #[cfg(not(windows))]
    {
        app_scoped_window_level(pinned, owner_focused, dialog_open)
    }
}

fn window_level_request_needed(
    current: Option<egui::viewport::WindowLevel>,
    desired: egui::viewport::WindowLevel,
    settle_frames: u8,
) -> bool {
    current != Some(desired) || settle_frames > 0
}

#[cfg(test)]
mod add_track_configuration_tests {
    use opentrack_core::routing::InputRoute;

    #[test]
    fn mono_input_choice_maps_to_the_matching_persisted_route() {
        // The picker stores the historical spellings for the two channels the
        // capture bus provides, so existing projects and recordings agree.
        assert_eq!(
            InputRoute::MonoIn { channel: 1 }.persisted(),
            "Left - Stereo In"
        );
        assert_eq!(
            InputRoute::MonoIn { channel: 2 }.persisted(),
            "Right - Stereo In"
        );
        assert_eq!(
            InputRoute::parse("Left - Stereo In"),
            Ok(InputRoute::MonoIn { channel: 1 })
        );
        assert_eq!(
            InputRoute::parse("Right - Stereo In"),
            Ok(InputRoute::MonoIn { channel: 2 })
        );
    }
}

#[cfg(test)]
mod save_prompt_window_tests {
    use super::*;
    #[test]
    fn cancel_save_prompt_restores_tool_visibility_and_focuses_only_on_call() {
        let ctx = egui::Context::default();
        ctx.set_embed_viewports(false);
        let mut visibility = SavePromptVisibility::default();
        let mut active = true;
        let tool = egui::ViewportId::from_hash_of("test-channel");
        let mut cancel = Pos2::ZERO;
        for frame in 0..4 {
            let mut raw = egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(900.0, 500.0))),
                time: Some(frame as f64 * 0.05),
                ..Default::default()
            };
            raw.viewports.insert(tool, egui::ViewportInfo::default());
            if frame >= 2 {
                raw.events = vec![
                    egui::Event::PointerMoved(cancel),
                    egui::Event::PointerButton {
                        pos: cancel,
                        button: egui::PointerButton::Primary,
                        pressed: frame == 2,
                        modifiers: egui::Modifiers::NONE,
                    },
                ];
            }
            let mut out = ctx.run_ui(raw, |_| {
                ctx.show_viewport_deferred(tool, egui::ViewportBuilder::default(), |_, _| {});
                if matches!(unsaved_prompt_ui(&ctx), Some(UnsavedChoice::Cancel)) {
                    active = false;
                }
                visibility.sync(&ctx, active);
            });
            out.textures_delta.clear();
            if frame == 1 {
                cancel = out
                    .shapes
                    .iter()
                    .find_map(|shape| match &shape.shape {
                        egui::Shape::Text(text) if text.galley.text() == "Cancel" => {
                            Some(text.pos + text.galley.size() * 0.5)
                        }
                        _ => None,
                    })
                    .expect("save prompt has a Cancel action");
            }
            let expected_visible = frame == 3;
            assert!(out.viewport_output[&tool].commands.iter().any(|cmd| matches!(cmd, egui::ViewportCommand::Visible(value) if *value == expected_visible)));
            let focused = out.viewport_output[&egui::ViewportId::ROOT]
                .commands
                .iter()
                .any(|cmd| matches!(cmd, egui::ViewportCommand::Focus));
            assert_eq!(
                focused,
                frame == 0,
                "focus the prompt on call, without stealing focus every frame"
            );
            out.textures_delta.clear();
        }
        assert!(!active);
        assert!(visibility.hidden.is_empty());
    }

    #[test]
    fn save_prompt_hides_all_sibling_viewports_and_restores_only_live_ones() {
        let transport = egui::ViewportId::from_hash_of("transport");
        let channel = egui::ViewportId::from_hash_of("channel");
        let plugin = egui::ViewportId::from_hash_of("plugin");
        let mut state = SavePromptVisibility::default();
        let mut present = HashSet::from([egui::ViewportId::ROOT, transport, channel]);
        let (entered, commands) = state.update(true, &present);
        assert!(entered);
        assert_eq!(
            commands.into_iter().collect::<HashMap<_, _>>(),
            HashMap::from([(transport, false), (channel, false)])
        );
        present.insert(plugin);
        let (entered, commands) = state.update(true, &present);
        assert!(
            !entered,
            "do not repeatedly steal focus while the modal is open"
        );
        assert!(commands.contains(&(plugin, false)));
        present.remove(&channel);
        let (_, commands) = state.update(false, &present);
        assert_eq!(
            commands.into_iter().collect::<HashMap<_, _>>(),
            HashMap::from([(transport, true), (plugin, true)])
        );
        assert!(state.update(false, &present).1.is_empty());
    }

    #[test]
    fn transport_focus_keeps_the_app_pin_and_modal_priority_releases_it() {
        let ctx = egui::Context::default();
        let tool = egui::ViewportId::from_hash_of("transport");
        let mut input = egui::RawInput::default();
        input
            .viewports
            .get_mut(&egui::ViewportId::ROOT)
            .unwrap()
            .focused = Some(false);
        input.viewports.insert(
            tool,
            egui::ViewportInfo {
                focused: Some(true),
                ..Default::default()
            },
        );
        let mut out = ctx.run_ui(input, |ui| {
            assert!(app_has_focused_viewport(ui.ctx()));
            assert_eq!(
                app_scoped_window_level(true, app_has_focused_viewport(ui.ctx()), false),
                egui::viewport::WindowLevel::AlwaysOnTop
            );
            assert_eq!(
                app_scoped_window_level(true, app_has_focused_viewport(ui.ctx()), true),
                egui::viewport::WindowLevel::Normal
            );
        });
        out.textures_delta.clear();
        assert_eq!(
            app_scoped_window_level(true, false, false),
            egui::viewport::WindowLevel::Normal
        );
    }
}

#[cfg(all(test, not(windows)))]
mod channel_window_level_tests {
    use super::{channel_window_level, window_level_request_needed};
    use eframe::egui::viewport::WindowLevel;

    #[test]
    fn channel_pin_stays_active_while_either_open_track_window_has_focus() {
        assert_eq!(
            channel_window_level(true, true, false),
            WindowLevel::AlwaysOnTop
        );
        assert_eq!(
            channel_window_level(true, false, false),
            WindowLevel::Normal,
            "release the app-scoped level when focus leaves OpenTrack"
        );
        assert_eq!(
            channel_window_level(true, true, true),
            WindowLevel::Normal,
            "confirmation dialogs must remain above Channel Settings"
        );
    }

    #[test]
    fn compositor_level_is_reasserted_until_settled() {
        assert!(window_level_request_needed(
            None,
            WindowLevel::AlwaysOnTop,
            0
        ));
        assert!(window_level_request_needed(
            Some(WindowLevel::AlwaysOnTop),
            WindowLevel::AlwaysOnTop,
            2
        ));
        assert!(!window_level_request_needed(
            Some(WindowLevel::AlwaysOnTop),
            WindowLevel::AlwaysOnTop,
            0
        ));
    }
}

fn viewport_builder(
    title: impl Into<String>,
    default_size: Vec2,
    minimum_size: Vec2,
    restore_bounds: Option<&WindowBounds>,
) -> egui::ViewportBuilder {
    let mut builder = egui::ViewportBuilder::default()
        .with_title(title)
        // Each child window is a separate Wayland/X11 toplevel, so it needs the
        // same application id as the main window for the desktop to resolve its
        // icon; otherwise it falls back to a generic placeholder.
        .with_app_id("opentrack")
        .with_inner_size(default_size)
        .with_min_inner_size(minimum_size)
        .with_resizable(true)
        .with_icon(crate::icons::opentrack_icon());
    if let Some(bounds) = restore_bounds {
        builder = builder
            .with_position(Pos2::new(bounds.left as f32, bounds.top as f32))
            .with_inner_size(Vec2::new(
                bounds.inner_width.unwrap_or(bounds.width) as f32,
                bounds.inner_height.unwrap_or(bounds.height) as f32,
            ));
    }
    builder
}

fn apply_viewport_bounds(ctx: &egui::Context, bounds: &WindowBounds) {
    ctx.send_viewport_cmd(egui::ViewportCommand::OuterPosition(Pos2::new(
        bounds.left as f32,
        bounds.top as f32,
    )));
    ctx.send_viewport_cmd(egui::ViewportCommand::InnerSize(Vec2::new(
        bounds.inner_width.unwrap_or(bounds.width) as f32,
        bounds.inner_height.unwrap_or(bounds.height) as f32,
    )));
}

fn viewport_interaction(ctx: &egui::Context) -> (bool, bool, bool, bool) {
    ctx.input(|input| {
        let mut pointer_event = false;
        let mut pointer_released = false;
        let mut key_pressed = false;
        for event in &input.events {
            match event {
                egui::Event::PointerButton { pressed, .. } => {
                    pointer_event = true;
                    pointer_released |= !pressed;
                }
                egui::Event::Key { pressed: true, .. } => key_pressed = true,
                _ => {}
            }
        }
        let pointer_down = [
            egui::PointerButton::Primary,
            egui::PointerButton::Secondary,
            egui::PointerButton::Middle,
        ]
        .into_iter()
        .any(|button| input.pointer.button_down(button));
        (pointer_event, pointer_released, key_pressed, pointer_down)
    })
}

