    /// Shows or hides one track's automation lane in the arrange.
    fn toggle_automation_lane_visibility(&mut self, track_id: u64) -> bool {
        if self.arrange_view_state.automation_visible.remove(&track_id) {
            return false;
        }
        self.arrange_view_state.automation_visible.insert(track_id);
        true
    }

    fn show_automation_panel(&mut self, ctx: &egui::Context) {
        if !self.automation_panel_open {
            return;
        }
        let mut open = true;
        let mut toggle = None;
        let mut hide_all = false;
        let rows = self
            .data
            .project
            .tracks
            .iter()
            .filter(|track| {
                !track.automation_lanes.is_empty()
                    || self.data.project.selected_track
                        == self
                            .data
                            .project
                            .tracks
                            .iter()
                            .position(|candidate| candidate.id == track.id)
                            .map(|index| index as u32)
            })
            .map(|track| {
                (
                    track.id,
                    track.name.clone(),
                    track
                        .automation_lanes
                        .iter()
                        .map(|lane| {
                            let label = match lane.target {
                                opentrack_core::automation::AutomationTarget::TrackVolume => {
                                    "Volume"
                                }
                            };
                            (label, lane.points.len())
                        })
                        .collect::<Vec<_>>(),
                )
            })
            .collect::<Vec<_>>();
        let response = egui::Window::new("Automation Panel")
            .id(Id::new("automation-panel"))
            .order(egui::Order::Foreground)
            .collapsible(false)
            .resizable(true)
            .default_size(Vec2::new(380.0, 300.0))
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(
                        "Lanes found on the selected tracks and every track with stored automation.",
                    )
                    .small()
                    .color(theme::palette(ui).muted),
                );
                ui.separator();
                if rows.is_empty() {
                    ui.label("No track has an automation lane yet.");
                }
                for (track_id, name, lanes) in &rows {
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(name).strong());
                        let visible = self
                            .arrange_view_state
                            .automation_visible
                            .contains(track_id);
                        if ui
                            .small_button(if visible { "Hide in Arrange" } else { "Show in Arrange" })
                            .clicked()
                        {
                            toggle = Some(*track_id);
                        }
                    });
                    if lanes.is_empty() {
                        ui.label(
                            egui::RichText::new("No lanes yet. Draw one in the arrange.")
                                .small()
                                .color(theme::palette(ui).muted),
                        );
                    }
                    for (label, points) in lanes {
                        ui.label(format!("    {label}: {points} point(s)"));
                    }
                }
                ui.separator();
                if ui.button("Hide All").clicked() {
                    hide_all = true;
                }
            });
        dismiss_window_on_outside_click(
            ctx,
            Id::new("automation-panel"),
            &mut open,
            response.as_ref(),
        );
        self.automation_panel_open = open;
        if let Some(track_id) = toggle {
            self.toggle_automation_lane_visibility(track_id);
        }
        if hide_all {
            self.arrange_view_state.automation_visible.clear();
        }
    }

    /// Opens the timecode dialog seeded from the timecode at the cursor.
    fn open_timecode_dialog(&mut self) {
        let cursor = self.data.transport.position_beats.max(0.0);
        self.timecode_dialog = Some(self.data.project.timecode_seconds_at(cursor).max(0.0));
    }

    /// Makes the typed timecode the timecode at the cursor, as one undo step.
    fn apply_timecode_at_cursor(&mut self, seconds: f64) {
        if !seconds.is_finite() || seconds < 0.0 {
            self.status_message = "Enter a non-negative timecode".to_owned();
            return;
        }
        let cursor = self.data.transport.position_beats.max(0.0);
        let mut candidate = self.data.project.clone();
        if !candidate.set_timecode_at_cursor(cursor, seconds) {
            self.status_message = "That timecode is outside the supported range".to_owned();
            return;
        }
        if (candidate.timecode_offset_seconds - self.data.project.timecode_offset_seconds).abs()
            <= 1e-9
        {
            self.status_message = "The timecode at the cursor is already that value".to_owned();
            return;
        }
        self.project_history.finish_frame(&self.data.project, true);
        if !self
            .project_history
            .begin(&self.data.project, self.modified)
        {
            self.status_message =
                "Cannot set the timecode: undo snapshot is unavailable".to_owned();
            return;
        }
        self.project_history.label_next("Set Timecode");
        self.data.project = candidate;
        self.project_history.commit_after_frame = true;
        self.mark_modified();
        self.status_message = format!(
            "Timecode at the cursor set to {}",
            format_timecode(seconds, 30)
        );
    }

    fn show_timecode_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut seconds) = self.timecode_dialog.take() else {
            return;
        };
        let mut open = true;
        let mut apply = false;
        let mut cancel = false;
        let cursor = self.data.transport.position_beats.max(0.0);
        let response = egui::Window::new("Set Timecode at Cursor")
            .id(Id::new("set-timecode"))
            .order(egui::Order::Foreground)
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.set_min_width(300.0);
                ui.label(format!(
                    "The cursor sits at beat {cursor:.3}, {}",
                    format_timecode(cursor * 60.0 / self.data.project.tempo_bpm.max(1.0), 30)
                ));
                ui.horizontal(|ui| {
                    ui.label("Timecode (s)");
                    ui.add(
                        egui::DragValue::new(&mut seconds)
                            .range(0.0..=359_999.0)
                            .speed(1.0),
                    );
                });
                ui.label(
                    egui::RichText::new(format!("Shown as {}", format_timecode(seconds, 30)))
                        .small()
                        .color(theme::palette(ui).muted),
                );
                ui.horizontal(|ui| {
                    if ui.button("Apply").clicked() || ui.input(|i| i.key_pressed(egui::Key::Enter))
                    {
                        apply = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
            });
        dismiss_window_on_outside_click(ctx, Id::new("set-timecode"), &mut open, response.as_ref());
        if apply {
            self.apply_timecode_at_cursor(seconds);
        } else if !cancel && open {
            self.timecode_dialog = Some(seconds);
        }
    }

    /// Splits the selected MIDI part into one track per distinct pitch.
    fn explode_selected_midi_part_by_pitch(&mut self) {
        self.explode_selected_midi_part(true);
    }

    /// Splits the selected MIDI part into one track per pitch or per channel.
    fn explode_selected_midi_part(&mut self, by_pitch: bool) {
        if self.is_recording() {
            self.status_message = "Stop recording before exploding a MIDI part".to_owned();
            return;
        }
        let Some(track_id) = self
            .data
            .project
            .selected_track
            .and_then(|index| self.data.project.tracks.get(index as usize))
            .map(|track| track.id)
        else {
            self.status_message = "Select a MIDI track before exploding a part".to_owned();
            return;
        };
        let Some(part_id) = self.data.project.selected_midi_part_id else {
            self.status_message = if by_pitch {
                "Select a MIDI part to explode by pitch".to_owned()
            } else {
                "Select a MIDI part to explode by channel".to_owned()
            };
            return;
        };
        let mut candidate = self.data.project.clone();
        let exploded = if by_pitch {
            candidate.explode_midi_part_by_pitch(track_id, part_id, 16)
        } else {
            candidate.explode_midi_part_by_channel(track_id, part_id, 16)
        };
        let parts = match exploded {
            Ok(parts) => parts,
            Err(message) => {
                self.status_message = message;
                return;
            }
        };
        self.project_history.finish_frame(&self.data.project, true);
        if !self
            .project_history
            .begin(&self.data.project, self.modified)
        {
            self.status_message = "Cannot explode: undo snapshot is unavailable".to_owned();
            return;
        }
        self.project_history.label_next(if by_pitch {
            "Explode Pitches"
        } else {
            "Explode"
        });
        let first_part = parts.first().copied();
        let first_track = first_part.and_then(|wanted| {
            candidate.tracks.iter().position(|track| {
                track
                    .midi_parts
                    .iter()
                    .any(|candidate_part| candidate_part.id == wanted)
            })
        });
        self.data.project = candidate;
        if let Some(index) = first_track {
            let track_id = self.data.project.tracks[index].id;
            self.data.project.selected_track = Some(index as u32);
            self.arrange_view_state.selected_track_ids.clear();
            self.arrange_view_state.selected_track_ids.insert(track_id);
            self.arrange_view_state.selection_anchor_track_id = Some(track_id);
        }
        self.data.project.selected_midi_part_id = first_part;
        self.selected_midi_note_ids.clear();
        self.project_history.commit_after_frame = true;
        self.rebuild_audio_plan();
        self.mark_modified();
        self.status_message = format!(
            "Exploded the MIDI part into {} {} track(s); Undo restores it",
            parts.len(),
            if by_pitch { "pitch" } else { "channel" }
        );
    }

    /// Builds an N-note tuplet from the selected notes as one undo step.
    fn build_note_tuplet(&mut self, count: u8, span_beats: f64) {
        let Some(part_id) = self.data.project.selected_midi_part_id else {
            self.status_message = "Select a MIDI part before building a tuplet".to_owned();
            return;
        };
        let ids = self
            .selected_midi_note_ids
            .iter()
            .copied()
            .collect::<Vec<_>>();
        let mut candidate = self.data.project.clone();
        let Some(part) = candidate
            .tracks
            .iter_mut()
            .flat_map(|track| track.midi_parts.iter_mut())
            .find(|part| part.id == part_id)
        else {
            self.status_message = "The selected MIDI part is no longer in the project".to_owned();
            return;
        };
        let changed =
            match opentrack_core::midi_transform::build_tuplet(part, &ids, count, span_beats) {
                Ok(changed) => changed,
                Err(message) => {
                    self.status_message = message;
                    return;
                }
            };
        if changed == 0 {
            self.status_message = "The selected notes are already on that tuplet grid".to_owned();
            return;
        }
        self.project_history.finish_frame(&self.data.project, true);
        if !self
            .project_history
            .begin(&self.data.project, self.modified)
        {
            self.status_message =
                "Cannot build the tuplet: undo snapshot is unavailable".to_owned();
            return;
        }
        self.project_history.label_next("Build N-Tuplet");
        self.data.project = candidate;
        self.project_history.commit_after_frame = true;
        self.rebuild_audio_plan();
        self.mark_modified();
        self.status_message = format!(
            "Built a {count}-note tuplet over {span_beats:.3} beat(s); Undo restores the notes"
        );
    }

    /// Opens the tuplet dialog seeded from the selection.
    fn open_tuplet_dialog(&mut self) {
        if self.data.project.selected_midi_part_id.is_none() {
            self.status_message = "Select a MIDI part before building a tuplet".to_owned();
            return;
        }
        let notes = self
            .data
            .project
            .selected_midi_part_id
            .and_then(|part_id| {
                self.data
                    .project
                    .tracks
                    .iter()
                    .flat_map(|track| track.midi_parts.iter())
                    .find(|part| part.id == part_id)
            })
            .map(|part| {
                let selected = part
                    .notes
                    .iter()
                    .filter(|note| {
                        self.selected_midi_note_ids.is_empty()
                            || self.selected_midi_note_ids.contains(&note.id)
                    })
                    .collect::<Vec<_>>();
                let count = selected.len().clamp(2, 16) as u8;
                let start = selected
                    .iter()
                    .map(|note| note.start_beats)
                    .fold(f64::INFINITY, f64::min);
                let end = selected
                    .iter()
                    .map(|note| note.start_beats + note.duration_beats)
                    .fold(f64::NEG_INFINITY, f64::max);
                let span = if start.is_finite() && end > start {
                    end - start
                } else {
                    1.0
                };
                (count, span.clamp(0.0625, 64.0))
            })
            .unwrap_or((2, 1.0));
        self.tuplet_dialog = Some(notes);
    }

    fn show_tuplet_dialog(&mut self, ctx: &egui::Context) {
        let Some((mut count, mut span)) = self.tuplet_dialog.take() else {
            return;
        };
        let mut open = true;
        let mut apply = false;
        let mut cancel = false;
        let response = egui::Window::new("Build N-Tuplet")
            .id(Id::new("build-tuplet"))
            .order(egui::Order::Foreground)
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.set_min_width(300.0);
                ui.label("Fits the selected notes evenly into the tuplet");
                egui::Grid::new("build-tuplet-grid")
                    .num_columns(2)
                    .spacing([10.0, 4.0])
                    .show(ui, |ui| {
                        ui.label("Notes");
                        ui.add(egui::DragValue::new(&mut count).range(2..=16));
                        ui.end_row();
                        ui.label("Span (beats)");
                        ui.add(
                            egui::DragValue::new(&mut span)
                                .range(0.0625..=64.0)
                                .speed(0.0625),
                        );
                        ui.end_row();
                    });
                ui.label(
                    egui::RichText::new(
                        "Select exactly this many notes, or change the count. The span stops at the part end.",
                    )
                    .small()
                    .color(theme::palette(ui).muted),
                );
                ui.horizontal(|ui| {
                    if ui.button("Build").clicked()
                        || ui.input(|i| i.key_pressed(egui::Key::Enter))
                    {
                        apply = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
            });
        dismiss_window_on_outside_click(ctx, Id::new("build-tuplet"), &mut open, response.as_ref());
        if apply {
            self.build_note_tuplet(count, span);
        } else if !cancel && open {
            self.tuplet_dialog = Some((count, span));
        }
    }

    /// Applies a fixed velocity or a ramp to the selected notes.
    fn insert_note_velocities(&mut self, start: u8, end: u8) {
        let Some(part_id) = self.data.project.selected_midi_part_id else {
            self.status_message = "Select a MIDI part before inserting velocities".to_owned();
            return;
        };
        let ids = self
            .selected_midi_note_ids
            .iter()
            .copied()
            .collect::<Vec<_>>();
        let mut candidate = self.data.project.clone();
        let Some(part) = candidate
            .tracks
            .iter_mut()
            .flat_map(|track| track.midi_parts.iter_mut())
            .find(|part| part.id == part_id)
        else {
            self.status_message = "The selected MIDI part is no longer in the project".to_owned();
            return;
        };
        let changed = if start == end {
            opentrack_core::midi_transform::set_velocity(part, &ids, start)
        } else {
            opentrack_core::midi_transform::ramp_velocity(part, &ids, start, end)
        };
        if changed == 0 {
            self.status_message = "No note velocity changed".to_owned();
            return;
        }
        self.project_history.finish_frame(&self.data.project, true);
        if !self
            .project_history
            .begin(&self.data.project, self.modified)
        {
            self.status_message =
                "Cannot insert velocities: undo snapshot is unavailable".to_owned();
            return;
        }
        self.project_history.label_next("Insert Velocities");
        self.data.project = candidate;
        self.project_history.commit_after_frame = true;
        self.rebuild_audio_plan();
        self.mark_modified();
        self.status_message = if start == end {
            format!("Set {changed} note(s) to velocity {start}; Undo restores them")
        } else {
            format!("Ramped {changed} note(s) from velocity {start} to {end}; Undo restores them")
        };
    }

