#[cfg(test)]
mod undo_history_tests {
    use super::*;

    fn app_with_steps() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.project.add_track(TrackKind::Audio);
        app.project_history.clear();

        // Three labelled steps through the ordinary command path.
        for (index, name) in ["One", "Two", "Three"].iter().enumerate() {
            app.project_history.begin(&app.data.project, app.modified);
            app.project_history.label_next(name);
            app.data
                .project
                .add_audio_clip(
                    0,
                    PathBuf::from(format!("{name}.wav")),
                    index as f64 * 4.0,
                    2.0,
                )
                .unwrap();
            app.project_history.commit_after_frame = true;
            app.project_history.finish_frame(&app.data.project, true);
        }
        app
    }

    #[test]
    fn the_history_lists_labels_most_recent_first() {
        let app = app_with_steps();
        let steps = app.project_history.steps();
        assert_eq!(steps.len(), 3);
        assert_eq!(
            steps
                .iter()
                .map(|step| step.label.as_str())
                .collect::<Vec<_>>(),
            vec!["Three", "Two", "One"],
            "the most recent step is first"
        );
        assert!(steps.iter().all(|step| !step.redo && step.bytes > 0));
        assert_eq!(app.project_history.counts(), (3, 0));
    }

    #[test]
    fn jumping_back_and_forward_moves_the_whole_history() {
        let mut app = app_with_steps();

        // Two steps back leaves one event.
        let restored = app
            .project_history
            .jump_back(&app.data.project, 2)
            .expect("two steps back");
        assert_eq!(restored.tracks[0].clips.len(), 1);
        let (undo, redo) = app.project_history.counts();
        assert_eq!((undo, redo), (1, 2));

        // The undone steps are listed as redo entries.
        let steps = app.project_history.steps();
        assert_eq!(steps.len(), 3);
        assert!(!steps[0].redo, "the remaining undo step comes first");
        assert!(
            steps[1].redo && steps[2].redo,
            "then the undone steps, newest first"
        );
        assert_eq!(steps[1].label, "Three");

        // Forward again returns to three events.
        let restored = app
            .project_history
            .jump_forward(&restored, 2)
            .expect("two steps forward");
        assert_eq!(restored.tracks[0].clips.len(), 3);
        assert_eq!(app.project_history.counts(), (3, 0));

        // Asking for more steps than exist moves only what is available, and
        // asking when nothing is available reports failure.
        assert!(app.project_history.jump_back(&restored, 99).is_some());
        assert_eq!(app.project_history.counts(), (0, 3));
        assert!(app.project_history.jump_back(&restored, 1).is_none());
    }

    #[test]
    fn a_step_without_a_label_is_listed_as_a_generic_edit() {
        let mut app = app_with_steps();
        app.project_history.begin(&app.data.project, app.modified);
        app.data.project.tracks[0].name = "Renamed".to_owned();
        app.project_history.commit_after_frame = true;
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Edit");
    }

    #[test]
    fn a_real_command_labels_its_own_step() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.add_track(TrackKind::Audio);
        let id = app
            .data
            .project
            .add_audio_clip(0, PathBuf::from("a.wav"), 0.0, 2.0)
            .unwrap();
        app.project_history.clear();

        app.arrange_view_state.audio_events.select_many([id]);
        app.set_selected_audio_events_muted(true);
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Mute Events");

        app.arrange_view_state.audio_events.select_many([id]);
        app.nudge_selected_audio_events(true);
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Nudge");
    }

    #[test]
    fn the_history_window_renders_its_steps() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx.clone());
        let mut app = app_with_steps();
        app.undo_history_open = true;

        let mut texts = Vec::new();
        for frame in 0..2 {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1000.0, 700.0))),
                    time: Some(frame as f64 * 0.05),
                    ..Default::default()
                },
                |_| app.show_undo_history(&ctx),
            );
            output.textures_delta.clear();
            if frame == 0 {
                continue;
            }
            fn collect(shape: &egui::Shape, texts: &mut Vec<String>) {
                match shape {
                    egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                    egui::Shape::Vec(shapes) => {
                        for shape in shapes {
                            collect(shape, texts);
                        }
                    }
                    _ => {}
                }
            }
            for shape in &output.shapes {
                collect(&shape.shape, &mut texts);
            }
        }
        let joined = texts.join("\n");
        assert!(joined.contains("Undo History"), "{joined}");
        assert!(joined.contains("3 undo step(s)"), "{joined}");
        assert!(joined.contains("Three"), "{joined}");
        assert!(joined.contains("One"), "{joined}");
    }
}

#[cfg(test)]
mod autoscroll_tests {
    use super::*;

    fn app_with_view() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.project.add_track(TrackKind::Audio);
        app.arrange_view_state.last_view_width = 1000.0;
        app.arrange_view_state.timeline_zoom = 1.0;
        app.arrange_view_state.timeline_scroll_x = 0.0;
        app
    }

    #[test]
    fn the_page_rule_leaves_the_playhead_alone_while_it_is_visible() {
        let mut app = app_with_view();
        // 20.4 px per bar at zoom 1: beat 20 sits well inside the view.
        assert_eq!(
            app.arrange_view_state
                .autoscroll_target(20.0, app.data.project.beats_per_bar),
            None
        );
    }

    #[test]
    fn the_page_rule_brings_the_playhead_back_to_the_left_tenth() {
        let mut app = app_with_view();
        // Beat 400 is far right of the view.
        let target = app
            .arrange_view_state
            .autoscroll_target(400.0, app.data.project.beats_per_bar)
            .expect("the playhead is off screen");
        let bar_width = app.arrange_view_state.bar_width();
        let playhead_x = 264.0 + (400.0 / 4.0) * bar_width - target;
        assert!(
            (playhead_x - (264.0 + 100.0)).abs() < 0.01,
            "the playhead lands at the left tenth: {playhead_x}"
        );

        // A rewind behind the left tenth scrolls back too.
        app.arrange_view_state.timeline_scroll_x = target;
        let back = app
            .arrange_view_state
            .autoscroll_target(4.0, app.data.project.beats_per_bar)
            .expect("the playhead is behind the view");
        assert!(back < target, "rewinding scrolls left: {back} < {target}");
        assert!(back >= 0.0);
    }

    #[test]
    fn autoscroll_follows_playback_only_when_enabled() {
        let ctx = egui::Context::default();
        let mut app = app_with_view();
        app.data.transport.position_beats = 400.0;
        app.data.transport.playing = true;

        // Off: nothing moves.
        app.autoscroll_arrange(&ctx);
        assert_eq!(app.arrange_view_state.timeline_scroll_x, 0.0);

        // On while playing: the view pages.
        app.arrange_view_state.autoscroll_enabled = true;
        app.autoscroll_arrange(&ctx);
        assert!(
            app.arrange_view_state.timeline_scroll_x > 0.0,
            "the view followed the playhead"
        );

        // Stopped: a seek does not move the view.
        let scrolled = app.arrange_view_state.timeline_scroll_x;
        app.data.transport.playing = false;
        app.data.transport.position_beats = 900.0;
        app.autoscroll_arrange(&ctx);
        assert_eq!(app.arrange_view_state.timeline_scroll_x, scrolled);
    }

    #[test]
    fn the_users_own_scrolling_wins_while_the_pointer_is_down() {
        let ctx = egui::Context::default();
        let mut app = app_with_view();
        app.arrange_view_state.autoscroll_enabled = true;
        app.data.transport.playing = true;
        app.data.transport.position_beats = 400.0;

        // A held pointer means the user is dragging the grid.
        let mut raw = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 600.0))),
            events: vec![egui::Event::PointerButton {
                pos: Pos2::new(500.0, 300.0),
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: egui::Modifiers::NONE,
            }],
            ..Default::default()
        };
        raw.time = Some(0.05);
        let mut output = ctx.run_ui(raw, |_| app.autoscroll_arrange(&ctx));
        output.textures_delta.clear();
        assert_eq!(
            app.arrange_view_state.timeline_scroll_x, 0.0,
            "autoscroll stands aside while the user drags"
        );

        // Releasing the pointer lets it resume on the next frame.
        let mut released = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 600.0))),
            events: vec![egui::Event::PointerButton {
                pos: Pos2::new(500.0, 300.0),
                button: egui::PointerButton::Primary,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            }],
            ..Default::default()
        };
        released.time = Some(0.10);
        let mut output = ctx.run_ui(released, |_| app.autoscroll_arrange(&ctx));
        output.textures_delta.clear();
        assert!(
            app.arrange_view_state.timeline_scroll_x > 0.0,
            "autoscroll resumes after the gesture"
        );
    }
}

#[cfg(test)]
mod marker_command_tests {
    use super::*;

    fn app_with_markers() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.project.add_marker(8.0, "Verse").expect("marker");
        app.data.project.add_marker(16.0, "Chorus").expect("marker");
        app.project_history.clear();
        app
    }

    #[test]
    fn inserting_a_marker_uses_the_playhead_and_one_undo_step() {
        let mut app = app_with_markers();
        app.data.transport.position_beats = 24.0;
        app.add_marker_at_playhead();
        assert_eq!(app.data.project.markers.len(), 3);
        let added = app
            .data
            .project
            .markers
            .iter()
            .find(|marker| (marker.beat - 24.0).abs() < 1e-9)
            .expect("the marker is at the playhead");
        assert_eq!(added.name, "Marker 3");
        assert!(app.modified);
        assert!(app.status_message.contains("Added marker"));
    }

    #[test]
    fn locating_markers_wraps_in_both_directions() {
        let mut app = app_with_markers();
        app.data.transport.position_beats = 0.0;
        app.locate_next_marker();
        assert_eq!(app.data.transport.position_beats, 8.0);
        app.locate_next_marker();
        assert_eq!(app.data.transport.position_beats, 16.0);
        // Past the last marker it wraps to the first.
        app.locate_next_marker();
        assert_eq!(app.data.transport.position_beats, 8.0);
        // And backwards from the first it wraps to the last.
        app.locate_previous_marker();
        assert_eq!(app.data.transport.position_beats, 16.0);
        assert!(app.status_message.contains("Chorus"));
    }

    #[test]
    fn markers_without_any_report_instead_of_moving() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.transport.position_beats = 4.0;
        app.locate_next_marker();
        assert_eq!(app.data.transport.position_beats, 4.0);
        assert_eq!(app.status_message, "This project has no markers");
    }

    #[test]
    fn renaming_and_removing_markers_are_undoable() {
        let mut app = app_with_markers();
        let verse = app.data.project.markers[0].id;
        app.rename_marker(verse, "Verse A".to_owned());
        assert_eq!(app.data.project.markers[0].name, "Verse A");
        app.remove_marker(verse);
        assert_eq!(app.data.project.markers.len(), 1);
        assert!(app.status_message.contains("Removed the marker"));
    }

    #[test]
    fn the_ruler_draws_each_marker_name() {
        let mut app = app_with_markers();
        app.data.project.add_track(TrackKind::Audio);
        app.arrange_view_state.last_view_width = 900.0;

        let ctx = egui::Context::default();
        let mut found = Vec::new();
        for frame in 0..2 {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 600.0))),
                    time: Some(frame as f64 * 0.05),
                    ..Default::default()
                },
                |ui| {
                    let _ = show_project(
                        ui,
                        &mut app.edit_tool,
                        &mut app.data.project,
                        &mut app.data.transport.position_beats,
                        true,
                        4,
                        44_100,
                        &HashMap::new(),
                        &HashMap::new(),
                        &HashMap::new(),
                        None,
                        &mut app.arrange_view_state,
                        &mut false,
                        &mut None,
                        &mut NativeWindowState::default(),
                        &mut None,
                        true,
                        &mut None,
                        false,
                    );
                },
            );
            output.textures_delta.clear();
            fn collect(shape: &egui::Shape, texts: &mut Vec<String>) {
                match shape {
                    egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                    egui::Shape::Vec(shapes) => {
                        for shape in shapes {
                            collect(shape, texts);
                        }
                    }
                    _ => {}
                }
            }
            found.clear();
            for shape in &output.shapes {
                collect(&shape.shape, &mut found);
            }
        }
        assert!(found.iter().any(|text| text == "Verse"), "{found:?}");
        assert!(found.iter().any(|text| text == "Chorus"), "{found:?}");
    }
}

#[cfg(test)]
mod zoom_command_tests {
    use super::*;

    fn app_with_event() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.project.add_track(TrackKind::Audio);
        // 8 s at 120 BPM is 16 beats.
        app.data
            .project
            .add_audio_clip(0, PathBuf::from("a.wav"), 0.0, 8.0)
            .unwrap();
        app.arrange_view_state.last_view_width = 1000.0;
        app
    }

    /// Beat drawn at a viewport x, using the same transform as the arrange.
    fn beat_at(app: &OpenTrackApp, x: f32) -> f64 {
        let bar_width = (1000.0 / 49.0
            * app
                .arrange_view_state
                .timeline_zoom
                .clamp(crate::timeline::MIN_ZOOM, crate::timeline::MAX_ZOOM))
        .max(4.0);
        crate::timeline::ruler_position_beats(
            x,
            264.0 - app.arrange_view_state.timeline_scroll_x,
            bar_width,
            app.data.project.beats_per_bar.max(1),
        )
    }

    #[test]
    fn zooming_in_and_out_keeps_the_anchor_beat_in_place() {
        let mut app = app_with_event();
        app.arrange_view_state.timeline_zoom = 1.0;
        app.arrange_view_state.timeline_scroll_x = 0.0;
        app.data.transport.position_beats = 0.0;

        // The playhead is the anchor when it is on screen.
        app.data.transport.position_beats = 24.0;
        let anchor_x = 264.0 + (24.0 / 4.0) as f32 * (1000.0 / 49.0);
        let before = beat_at(&app, anchor_x);
        let start_zoom = app.arrange_view_state.timeline_zoom;

        app.run_zoom_command(ZoomCommand::In);
        assert!(app.arrange_view_state.timeline_zoom > start_zoom);
        let after = beat_at(&app, anchor_x);
        assert!(
            (before - 24.0).abs() < 0.01,
            "the anchor starts on the playhead: {before}"
        );
        assert!(
            (after - before).abs() < 0.15,
            "the anchor moved: {before} -> {after}"
        );

        app.run_zoom_command(ZoomCommand::Out);
        assert!(
            (app.arrange_view_state.timeline_zoom - start_zoom).abs() < 1e-4,
            "in then out returns to the same zoom"
        );
        assert!((beat_at(&app, anchor_x) - before).abs() < 0.15);
    }

    #[test]
    fn zooming_stops_at_the_supported_limits() {
        let mut app = app_with_event();
        app.arrange_view_state.timeline_zoom = crate::timeline::MAX_ZOOM;
        app.run_zoom_command(ZoomCommand::In);
        assert_eq!(
            app.arrange_view_state.timeline_zoom,
            crate::timeline::MAX_ZOOM
        );
        app.arrange_view_state.timeline_zoom = crate::timeline::MIN_ZOOM;
        app.run_zoom_command(ZoomCommand::Out);
        assert_eq!(
            app.arrange_view_state.timeline_zoom,
            crate::timeline::MIN_ZOOM
        );
    }

    #[test]
    fn zoom_to_project_shows_the_whole_content() {
        let mut app = app_with_event();
        // Sixteen beats at four per bar is four bars.
        app.run_zoom_command(ZoomCommand::ToProject);
        let end_beat = 16.0;
        let end_x = 264.0
            + (end_beat / 4.0) as f32
                * (1000.0 / 49.0 * app.arrange_view_state.timeline_zoom).max(4.0)
            - app.arrange_view_state.timeline_scroll_x;
        assert!(
            end_x <= 264.0 + 1000.0,
            "the project end is inside the view: {end_x}"
        );
        assert!(end_x > 264.0, "the project end is right of the header");
        assert_eq!(app.status_message, "Zoomed to the whole project");
    }

    #[test]
    fn zoom_to_selection_uses_the_selection_then_the_loop() {
        let mut app = app_with_event();
        let id = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([id]);
        app.run_zoom_command(ZoomCommand::ToSelection);
        assert_eq!(app.status_message, "Zoomed to the selection");
        let selected_zoom = app.arrange_view_state.timeline_zoom;

        // Nothing selected and no loop: the command refuses instead of guessing.
        app.arrange_view_state.audio_events.clear_selection();
        app.data.project.loop_start_beats = 4.0;
        app.data.project.loop_end_beats = 4.0;
        app.run_zoom_command(ZoomCommand::ToSelection);
        assert!(
            app.status_message.contains("before zooming to a selection"),
            "status was {}",
            app.status_message
        );

        // With a loop range it falls back to the loop.
        app.data.project.loop_end_beats = 8.0;
        app.run_zoom_command(ZoomCommand::ToSelection);
        assert_eq!(app.status_message, "Zoomed to the selection");
        assert!(app.arrange_view_state.timeline_zoom > selected_zoom);
    }
}

#[cfg(test)]
mod selection_identity_tests {
    use super::*;

    /// Every surface reads `Project::selected_track`, so an event click has to
    /// leave the shared field on that event's track.
    #[test]
    fn clicking_an_event_selects_its_track_for_every_surface() {
        let ctx = egui::Context::default();
        let mut project = Project::default();
        project.add_track(TrackKind::Audio);
        project.add_track(TrackKind::Audio);
        project.tracks[0].name = "Drums".to_owned();
        project.tracks[1].name = "Bass".to_owned();
        let bass_track = project.tracks[1].id;
        let first = project
            .add_audio_clip(0, PathBuf::from("drums.wav"), 0.0, 8.0)
            .unwrap();
        // 4 s at 120 BPM is 8 beats, so the bass event covers beats 8 through 16.
        let second = project
            .add_audio_clip(1, PathBuf::from("bass.wav"), 8.0, 4.0)
            .unwrap();
        assert_ne!(first, second);

        let mut view = ArrangeViewState {
            show_inspector: false,
            ..Default::default()
        };
        let mut position = 0.0;
        let mut tool = EditTool::Select;
        let mut frame = |events: Vec<egui::Event>| {
            let mut out = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 600.0))),
                    events,
                    ..Default::default()
                },
                |ui| {
                    let _ = show_project(
                        ui,
                        &mut tool,
                        &mut project,
                        &mut position,
                        true,
                        4,
                        44_100,
                        &HashMap::new(),
                        &HashMap::new(),
                        &HashMap::new(),
                        None,
                        &mut view,
                        &mut false,
                        &mut None,
                        &mut NativeWindowState::default(),
                        &mut None,
                        true,
                        &mut None,
                        false,
                    );
                },
            );
            let _ = ctx.tessellate(std::mem::take(&mut out.shapes), out.pixels_per_point);
            out.textures_delta.clear();
        };
        frame(vec![]);
        frame(vec![]);

        // The second track row starts below the 22 px ruler and a 42 px first row.
        let point = Pos2::new(320.0, 85.0);
        for pressed in [true, false] {
            frame(vec![
                egui::Event::PointerMoved(point),
                egui::Event::PointerButton {
                    pos: point,
                    button: egui::PointerButton::Primary,
                    pressed,
                    modifiers: egui::Modifiers::NONE,
                },
            ]);
        }
        frame(vec![]);

        assert_eq!(
            view.audio_events.selected_ids(),
            vec![second],
            "the clicked event is the selection"
        );
        assert_eq!(
            project.selected_track,
            Some(1),
            "the shared track selection follows the clicked event"
        );
        let shared = project
            .selected_track
            .and_then(|index| project.tracks.get(index as usize))
            .map(|track| track.id);
        assert_eq!(
            shared,
            Some(bass_track),
            "Mixer and Channel Settings read this id"
        );
    }
}

#[cfg(test)]
mod project_recovery_tests {
    use super::*;

    fn autosave_fixture(name: &str) -> (PathBuf, OpenTrackApp) {
        let root = std::env::temp_dir().join(format!(
            "opentrack-autosave-app-{}-{name}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("Metadata")).expect("metadata");
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.tracks[0].name = "Guitar".to_owned();
        app.project_open = true;
        app.project_folder_managed = true;
        app.project_path = Some(root.join("Song.opr"));
        app.modified = true;
        app.last_autosave = Instant::now() - Duration::from_secs(120);
        (root, app)
    }

    #[test]
    fn unsaved_changes_are_copied_into_the_projects_recovery_folder() {
        let (root, mut app) = autosave_fixture("write");
        assert!(project_recovery::pending(&root).is_none());
        app.maybe_autosave();

        let pending = project_recovery::pending(&root).expect("autosave written");
        assert_eq!(
            pending.path.parent(),
            Some(root.join("Metadata").join("Recovery").as_path()),
            "the point lives in the project's recovery folder"
        );
        assert!(
            pending
                .path
                .file_name()
                .is_some_and(|name| name.to_string_lossy().starts_with("recovery-")),
            "points are timestamped so several can coexist"
        );
        let document = ProjectFile::read(&pending.path).expect("the copy is a real project file");
        assert_eq!(document.project.tracks.len(), 2);
        assert_eq!(document.project.tracks[0].name, "Guitar");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn an_unmodified_or_recording_project_keeps_no_recovery_copy() {
        let (root, mut app) = autosave_fixture("skip");
        app.modified = false;
        app.maybe_autosave();
        assert!(project_recovery::pending(&root).is_none());

        app.modified = true;
        app.data.transport.recording = true;
        app.last_autosave = Instant::now() - Duration::from_secs(120);
        app.maybe_autosave();
        assert!(
            project_recovery::pending(&root).is_none(),
            "a transport in record mode must not be snapshotted"
        );
        assert!(
            project_recovery::pending(&root).is_none(),
            "a take in progress must not be snapshotted"
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn autosaves_are_rate_limited_so_a_drag_does_not_rewrite_the_project() {
        let (root, mut app) = autosave_fixture("rate");
        app.maybe_autosave();
        let first = project_recovery::pending_points(&root)
            .first()
            .expect("written")
            .written;
        app.data.project.tracks[0].name = "Changed".to_owned();
        app.maybe_autosave();
        let second = project_recovery::pending_points(&root)
            .first()
            .expect("written")
            .written;
        assert_eq!(first, second, "the interval has not elapsed yet");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn recovering_replaces_the_project_with_the_recovery_copy() {
        let (root, mut app) = autosave_fixture("recover");
        app.maybe_autosave();
        let pending = project_recovery::pending(&root).expect("autosave");

        // The saved project loses a track; recovering must bring it back.
        app.data.project.tracks.pop();
        assert_eq!(app.data.project.tracks.len(), 1);
        app.project_recovery = Some(ProjectRecoveryPrompt {
            project_root: root.clone(),
            points: vec![pending],
        });
        assert!(app.modal_dialog_open());
        app.apply_recovered_changes(0);

        assert_eq!(app.data.project.tracks.len(), 2);
        assert_eq!(app.data.project.tracks[0].name, "Guitar");
        assert!(app.modified);
        assert!(app.project_recovery.is_none());
        assert!(
            project_recovery::pending(&root).is_some(),
            "the copy stays until the recovered project is saved"
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn opening_a_project_with_an_autosave_offers_the_unsaved_changes() {
        let (root, mut app) = autosave_fixture("detect");
        create_project_directory_layout(&root).expect("project layout");
        let project_file = root.join("Song.opr");

        // The autosave holds two tracks.
        app.maybe_autosave();
        assert!(project_recovery::pending(&root).is_some());

        // The saved file holds one track, so the two differ.
        app.data.project.tracks.pop();
        app.data.project.selected_track = None;
        let document = app.project_file().expect("document");
        document.write(&project_file).expect("write project");

        app.load_project(project_file.clone());
        assert!(
            app.project_recovery.is_some(),
            "opening a project with a recovery copy must offer it"
        );
        assert_eq!(app.data.project.tracks.len(), 1);
        assert!(app.modal_dialog_open());

        app.apply_recovered_changes(0);
        assert_eq!(
            app.data.project.tracks.len(),
            2,
            "recovering brings back the unsaved track"
        );
        assert_eq!(app.data.project.tracks[0].name, "Guitar");
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn the_recovery_autosave_preference_decides_whether_and_when_a_copy_is_written() {
        let (root, mut app) = autosave_fixture("preference");

        // Off: nothing is written, even well past the interval.
        app.metering_preferences.recovery_autosave = false;
        app.last_autosave = Instant::now() - Duration::from_secs(600);
        app.maybe_autosave();
        assert!(project_recovery::pending(&root).is_none());

        // On with the default interval: still waiting.
        app.metering_preferences.recovery_autosave = true;
        app.last_autosave = Instant::now() - Duration::from_secs(5);
        app.maybe_autosave();
        assert!(
            project_recovery::pending(&root).is_none(),
            "the default interval is 20 s, so 5 s is too early"
        );

        // A shorter interval makes the same amount of elapsed time enough.
        app.metering_preferences.recovery_autosave_seconds = 5;
        app.maybe_autosave();
        assert!(
            project_recovery::pending(&root).is_some(),
            "the configured interval is what gates the copy"
        );
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn saving_and_discarding_both_remove_the_recovery_copy() {
        let (root, mut app) = autosave_fixture("clear");
        app.maybe_autosave();
        assert!(project_recovery::pending(&root).is_some());
        app.clear_autosave();
        assert!(
            project_recovery::pending(&root).is_none(),
            "a completed save settles the recovery copy"
        );

        app.last_autosave = Instant::now() - Duration::from_secs(120);
        app.maybe_autosave();
        let pending = project_recovery::pending(&root).expect("autosave again");
        app.project_recovery = Some(ProjectRecoveryPrompt {
            project_root: root.clone(),
            points: vec![pending],
        });
        let ctx = egui::Context::default();
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 700.0))),
                ..Default::default()
            },
            |_| app.show_project_recovery(&ctx),
        );
        assert!(!output.shapes.is_empty(), "the prompt is drawn");
        let _ = ctx.tessellate(std::mem::take(&mut output.shapes), output.pixels_per_point);
        output.textures_delta.clear();
        let _ = std::fs::remove_dir_all(root);
    }
}

#[cfg(test)]
mod recording_recovery_tests {
    use super::*;

    /// Writes the exact state an abnormal exit leaves: a valid `fmt ` chunk, a
    /// data chunk whose length still says zero, and the samples after it.
    fn write_crashed_take(path: &Path, frames: usize) {
        let channels: u16 = 2;
        let sample_rate: u32 = 48_000;
        let block_align = channels * 4;
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"RIFF");
        bytes.extend_from_slice(&36_u32.to_le_bytes());
        bytes.extend_from_slice(b"WAVE");
        bytes.extend_from_slice(b"fmt ");
        bytes.extend_from_slice(&16_u32.to_le_bytes());
        bytes.extend_from_slice(&3_u16.to_le_bytes()); // IEEE float
        bytes.extend_from_slice(&channels.to_le_bytes());
        bytes.extend_from_slice(&sample_rate.to_le_bytes());
        bytes.extend_from_slice(&(sample_rate * u32::from(block_align)).to_le_bytes());
        bytes.extend_from_slice(&block_align.to_le_bytes());
        bytes.extend_from_slice(&32_u16.to_le_bytes());
        bytes.extend_from_slice(b"data");
        bytes.extend_from_slice(&0_u32.to_le_bytes());
        for index in 0..frames {
            let value = (index as f32) / 48_000.0;
            bytes.extend_from_slice(&value.to_le_bytes());
            bytes.extend_from_slice(&(-value).to_le_bytes());
        }
        std::fs::write(path, bytes).expect("write crashed take");
    }

    fn recovery_fixture(name: &str) -> (PathBuf, OpenTrackApp, recording_recovery::PendingTake) {
        let root = std::env::temp_dir().join(format!(
            "opentrack-recovery-app-{}-{name}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("Audio").join("Recordings")).expect("recordings");
        std::fs::create_dir_all(root.join("Metadata")).expect("metadata");

        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.data.project = Project::default();
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.tracks[0].name = "Audio 1".to_owned();
        let track_id = app.data.project.tracks[0].id;

        let path = root.join("Audio").join("Recordings").join("Take 001.wav");
        write_crashed_take(&path, 24_000);
        recording_recovery::begin(
            &root,
            &[(path.clone(), track_id, "Audio 1".to_owned(), 4.0)],
        )
        .expect("journal");
        let takes = recording_recovery::pending(&root, &app.data.project).expect("pending");
        assert_eq!(takes.len(), 1);
        (root, app, takes.into_iter().next().expect("one take"))
    }

    #[test]
    fn a_crashed_take_is_unreadable_until_recovery_repairs_it() {
        let (root, _app, take) = recovery_fixture("unreadable");
        assert!(
            AudioSource::open(&take.take.path).is_err(),
            "a header that was never finalized hides the audio, which is why recovery is needed"
        );
        let repaired = opentrack_audio::repair_take(&take.take.path).expect("repair");
        assert!(repaired.repaired);
        assert_eq!(repaired.frames, 24_000);
        let source = AudioSource::open(&take.take.path).expect("readable after repair");
        assert!((source.duration_seconds() - 0.5).abs() < 1e-6);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn restoring_a_take_repairs_the_header_places_a_clip_and_clears_the_journal() {
        let (root, mut app, take) = recovery_fixture("restore");
        app.restore_recovered_take(&take).expect("restore");

        let clips = &app.data.project.tracks[0].clips;
        assert_eq!(clips.len(), 1);
        assert_eq!(clips[0].source_path, take.take.path);
        assert!((clips[0].start_beats - 4.0).abs() < 1e-9);
        assert!((clips[0].duration_seconds - 0.5).abs() < 1e-6);
        assert!(
            app.data.audio_sources.contains_key(&take.take.path),
            "the restored take is ready to play without reopening the file"
        );
        assert!(app.modified);
        assert!(
            !recording_recovery::journal_path(&root).exists(),
            "the journal is cleared once the take belongs to the project"
        );
        assert!(
            !opentrack_audio::repair_take(&take.take.path)
                .expect("repair again")
                .repaired,
            "the header is only rebuilt once"
        );
        assert!(app.status_message.contains("Recovered Take 001.wav"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn restoring_reports_a_take_that_needs_a_new_track() {
        let (root, mut app, take) = recovery_fixture("new-track");
        app.data.project.tracks.clear();
        app.restore_recovered_take(&take).expect("restore");

        assert_eq!(app.data.project.tracks.len(), 1);
        assert_eq!(app.data.project.tracks[0].name, "Recovered Take");
        assert_eq!(app.data.project.tracks[0].clips.len(), 1);
        assert!(app.status_message.contains("a new audio track was created"));
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn discarding_a_take_keeps_the_file_outside_the_recording_folder() {
        let (root, mut app, take) = recovery_fixture("discard");
        app.recording_recovery = Some(RecordingRecoveryPrompt {
            project_root: root.clone(),
            takes: vec![take.clone()],
            error: None,
        });
        app.discard_recovered_take(&take).expect("discard");

        assert!(app.data.project.tracks[0].clips.is_empty());
        assert!(!take.take.path.exists());
        let discarded = root
            .join("Metadata")
            .join("Recording")
            .join("Discarded")
            .join("Take 001.wav");
        assert!(
            discarded.exists(),
            "the audio is moved aside rather than destroyed"
        );
        assert!(!recording_recovery::journal_path(&root).exists());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn the_recovery_prompt_only_lists_takes_that_need_a_decision() {
        let (root, mut app, take) = recovery_fixture("prompt");
        app.recording_recovery = Some(RecordingRecoveryPrompt {
            project_root: root.clone(),
            takes: vec![take.clone()],
            error: None,
        });
        assert!(app.modal_dialog_open());
        let ctx = egui::Context::default();
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1200.0, 700.0))),
                ..Default::default()
            },
            |_| app.show_recording_recovery(&ctx),
        );
        assert!(!output.shapes.is_empty(), "the prompt is drawn");
        let _ = ctx.tessellate(std::mem::take(&mut output.shapes), output.pixels_per_point);
        output.textures_delta.clear();
        let _ = std::fs::remove_dir_all(root);
    }
}

#[cfg(test)]
mod recording_history_tests {
    use super::*;
    static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    struct Fixture {
        root: PathBuf,
        paths: Vec<PathBuf>,
        imported: PathBuf,
        project: Project,
        history: ProjectHistory,
    }
    impl Fixture {
        fn new() -> Self {
            let root = std::env::temp_dir().join(format!(
                "opentrack-record-undo-{}-{}",
                std::process::id(),
                NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
            ));
            std::fs::create_dir(&root).unwrap();
            let imported = root.join("imported.wav");
            std::fs::write(&imported, b"existing audio").unwrap();
            let mut project = Project::default();
            project.add_track(TrackKind::Audio);
            project
                .add_audio_clip(0, imported.clone(), 0.0, 1.0)
                .unwrap();
            let mut history = ProjectHistory::default();
            history.saved(&project);
            history.begin(&project, false);
            let paths = vec![root.join("recorded1.wav"), root.join("recorded2.wav")];
            for path in &paths {
                std::fs::write(path, b"recorded audio").unwrap();
                project.add_audio_clip(0, path.clone(), 4.0, 1.0).unwrap();
            }
            history.unsaved_recordings.extend(paths.iter().cloned());
            history.pending_recording = Some(recording_undo::RecordingUndo::new(
                paths.clone(),
                root.join("Undo"),
            ));
            assert!(history.finish_frame(&project, true));
            Self {
                root,
                paths,
                imported,
                project,
                history,
            }
        }
    }
    impl Drop for Fixture {
        fn drop(&mut self) {
            self.history.clear();
            for p in &self.paths {
                let _ = std::fs::remove_file(p);
            }
            let _ = std::fs::remove_file(&self.imported);
            let _ = std::fs::remove_dir(self.root.join("Undo"));
            let _ = std::fs::remove_dir(&self.root);
        }
    }
    #[test]
    fn recording_undo_removes_files_redo_restores_exact_bytes_and_branch_discards_recovery() {
        let mut f = Fixture::new();
        f.project = f.history.undo(&f.project).unwrap();
        assert!(f.paths.iter().all(|p| !p.exists()));
        assert!(f.imported.exists());
        assert_eq!(f.project.tracks[0].clips.len(), 1);
        f.project = f.history.redo(&f.project).unwrap();
        for p in &f.paths {
            assert_eq!(std::fs::read(p).unwrap(), b"recorded audio");
        }
        f.project = f.history.undo(&f.project).unwrap();
        f.history.begin(&f.project, false);
        f.project.tracks[0].name = "new edit".into();
        assert!(f.history.finish_frame(&f.project, true));
        assert!(!f.history.can_redo());
        assert!(!f.root.join("Undo").exists());
        assert!(f.imported.exists());
    }
    #[test]
    fn failed_undo_or_redo_keeps_history_and_never_overwrites_another_file() {
        let mut f = Fixture::new();
        std::fs::remove_file(&f.paths[1]).unwrap();
        assert!(f.history.undo(&f.project).is_none());
        assert!(f.paths[0].exists());
        assert!(f.history.can_undo());
        std::fs::write(&f.paths[1], b"recorded audio").unwrap();
        f.project = f.history.undo(&f.project).unwrap();
        std::fs::write(&f.paths[0], b"new unrelated file").unwrap();
        assert!(f.history.redo(&f.project).is_none());
        assert_eq!(std::fs::read(&f.paths[0]).unwrap(), b"new unrelated file");
        assert!(f.history.can_redo());
        assert!(!f.paths[1].exists());
        std::fs::remove_file(&f.paths[0]).unwrap();
        f.project = f.history.redo(&f.project).unwrap();
        assert!(f.paths.iter().all(|p| p.exists()));
    }
    #[test]
    fn discarding_changes_restores_recordings_referenced_by_saved_project_even_after_redo_is_cleared()
     {
        let mut f = Fixture::new();
        f.history.saved(&f.project);
        f.project = f.history.undo(&f.project).unwrap();
        f.history.begin(&f.project, false);
        f.project.tracks[0].name = "branch".into();
        assert!(f.history.finish_frame(&f.project, true));
        assert!(!f.paths[0].exists());
        f.history.restore_saved_recordings().unwrap();
        assert!(f.paths.iter().all(|p| p.exists()));
    }
    #[test]
    fn discard_deletes_unsaved_recordings_but_preserves_imported_and_saved_recordings() {
        let mut f = Fixture::new();
        f.history.discard_recordings().unwrap();
        assert!(f.paths.iter().all(|p| !p.exists()));
        assert!(f.imported.exists());
        let mut saved = Fixture::new();
        saved.history.saved(&saved.project);
        saved.history.discard_recordings().unwrap();
        assert!(saved.paths.iter().all(|p| p.exists()));
        assert!(saved.imported.exists());
    }
    #[test]
    fn discard_deletes_takes_even_after_their_recording_undo_step_is_trimmed() {
        let mut f = Fixture::new();
        for i in 0..40 {
            f.history.begin(&f.project, false);
            f.project.tracks[0].name = format!("edit {i}");
            assert!(f.history.finish_frame(&f.project, true));
        }
        f.history.discard_recordings().unwrap();
        assert!(f.paths.iter().all(|p| !p.exists()));
        assert!(f.imported.exists());
    }
    #[test]
    fn next_take_name_does_not_reuse_an_undone_or_saved_recording_path() {
        let f = Fixture::new();
        let tracks = vec![(1, "Audio".into(), Some(AudioRecordRoute::Stereo))];
        let reserved = HashSet::from([f.root.join("Take 001.wav")]);
        assert_eq!(
            next_recording_paths(&f.root, &tracks, &reserved).unwrap(),
            vec![f.root.join("Take 002.wav")]
        );
    }
    #[test]
    fn ordinary_event_removal_undo_does_not_delete_imported_audio() {
        let mut f = Fixture::new();
        f.history.clear();
        f.history.begin(&f.project, false);
        f.project.tracks[0].clips.clear();
        assert!(f.history.finish_frame(&f.project, true));
        f.project = f.history.undo(&f.project).unwrap();
        assert!(f.imported.exists());
        assert!(f.paths.iter().all(|p| p.exists()));
    }
}

