#[cfg(test)]
mod track_navigation_tests {
    use super::*;

    fn app_with_tracks(count: usize) -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        for _ in 0..count {
            app.data.project.add_track(TrackKind::Audio);
        }
        app.data.project.selected_track = Some(0);
        app
    }

    #[test]
    fn up_and_down_move_the_track_selection_without_wrapping() {
        let mut app = app_with_tracks(3);
        app.navigate_track(1, false);
        assert_eq!(app.data.project.selected_track, Some(1));
        assert_eq!(app.arrange_view_state.selected_track_ids.len(), 1);
        app.navigate_track(1, false);
        assert_eq!(app.data.project.selected_track, Some(2));
        // Clamped at the last track instead of wrapping to the first.
        app.navigate_track(1, false);
        assert_eq!(app.data.project.selected_track, Some(2));
        app.navigate_track(-5, false);
        assert_eq!(app.data.project.selected_track, Some(0));
        assert!(app.status_message.contains("Selected"));
    }

    #[test]
    fn top_and_bottom_select_the_edges() {
        let mut app = app_with_tracks(4);
        app.navigate_track_edge(true, false);
        assert_eq!(app.data.project.selected_track, Some(3));
        app.navigate_track_edge(false, false);
        assert_eq!(app.data.project.selected_track, Some(0));

        // No tracks is reported rather than panicking.
        let mut empty = app_with_tracks(0);
        empty.navigate_track(1, false);
        assert!(empty.status_message.contains("no tracks"));
        empty.navigate_track_edge(true, false);
        assert!(empty.status_message.contains("no tracks"));
    }

    #[test]
    fn adding_to_the_selection_keeps_the_previous_tracks() {
        let mut app = app_with_tracks(3);
        app.navigate_track(1, false);
        app.navigate_track(1, true);
        assert_eq!(app.arrange_view_state.selected_track_ids.len(), 2);
        assert_eq!(app.data.project.selected_track, Some(2));
        assert!(app.status_message.contains("2 track(s) selected"));
        // The anchor is the track the selection moved to.
        assert_eq!(
            app.arrange_view_state.selection_anchor_track_id,
            Some(app.data.project.tracks[2].id)
        );
    }

    #[test]
    fn setting_a_locator_at_the_cursor_is_one_undo_step() {
        let mut app = app_with_tracks(1);
        app.data.transport.position_beats = 8.0;
        app.data.project.loop_start_beats = 0.0;
        app.data.project.loop_end_beats = 16.0;
        app.project_history.clear();

        app.set_locator_at_playhead(true);
        assert_eq!(app.data.project.loop_start_beats, 8.0);
        assert_eq!(app.data.project.loop_end_beats, 16.0, "the right stays put");
        assert!(app.status_message.contains("left locator"));
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Set Locators");

        app.data.transport.position_beats = 12.0;
        app.set_locator_at_playhead(false);
        assert_eq!(app.data.project.loop_start_beats, 8.0);
        assert_eq!(app.data.project.loop_end_beats, 12.0);
        assert!(app.status_message.contains("right locator"));

        // Setting the left past the right pushes the right forward.
        app.data.transport.position_beats = 20.0;
        app.set_locator_at_playhead(true);
        assert_eq!(app.data.project.loop_start_beats, 20.0);
        assert!(app.data.project.loop_end_beats > 20.0);
        assert!(app.data.project.validate().is_ok());
    }
}

#[cfg(test)]
mod transport_locate_tests {
    use super::*;

    fn app_with_events() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.add_track(TrackKind::Midi);
        app.data
            .project
            .add_audio_clip(0, PathBuf::from("a.wav"), 4.0, 2.0)
            .unwrap();
        app.data
            .project
            .add_audio_clip(0, PathBuf::from("b.wav"), 12.0, 2.0)
            .unwrap();
        app.data.project.add_midi_part(1, 8.0, 4.0).unwrap();
        // A newly added part becomes the MIDI selection; these tests choose
        // their own selection.
        app.data.project.selected_midi_part_id = None;
        app.project_history.clear();
        app
    }

    #[test]
    fn locating_events_moves_strictly_forward_and_back() {
        let mut app = app_with_events();
        app.data.transport.position_beats = 0.0;
        app.locate_next_event();
        assert_eq!(app.data.transport.position_beats, 4.0);
        app.locate_next_event();
        assert_eq!(app.data.transport.position_beats, 8.0);
        app.locate_next_event();
        assert_eq!(app.data.transport.position_beats, 12.0);
        assert!(app.status_message.contains("next event at beat 12.000"));
        // Past the last event it reports instead of jumping.
        app.locate_next_event();
        assert_eq!(app.data.transport.position_beats, 12.0);
        assert!(app.status_message.contains("no event after"));

        app.locate_previous_event();
        assert_eq!(app.data.transport.position_beats, 8.0);
        app.locate_previous_event();
        assert_eq!(app.data.transport.position_beats, 4.0);
        app.locate_previous_event();
        assert_eq!(app.data.transport.position_beats, 4.0);
        assert!(app.status_message.contains("no event before"));
    }

    #[test]
    fn locating_the_selection_uses_the_selected_span() {
        let mut app = app_with_events();
        let id = app.data.project.tracks[0].clips[1].id;
        app.arrange_view_state.audio_events.select_many([id]);
        app.locate_selection_start();
        assert_eq!(app.data.transport.position_beats, 12.0);
        app.locate_selection_end();
        // The second event is 2 beats long at 120 BPM.
        assert!((app.data.transport.position_beats - 16.0).abs() < 1e-9);
        assert!(app.status_message.contains("selection end"));

        // A MIDI part selection works the same way.
        let part = app.data.project.tracks[1].midi_parts[0].id;
        app.arrange_view_state.audio_events.clear_selection();
        app.data.project.selected_midi_part_id = Some(part);
        app.locate_selection_start();
        assert_eq!(app.data.transport.position_beats, 8.0);
    }

    #[test]
    fn locators_loop_and_play_use_the_selection_as_one_undo_step() {
        let mut app = app_with_events();
        app.arrange_view_state.audio_events.select_many([
            app.data.project.tracks[0].clips[0].id,
            app.data.project.tracks[0].clips[1].id,
        ]);
        app.locators_to_selection();
        assert_eq!(app.data.project.loop_start_beats, 4.0);
        assert_eq!(app.data.project.loop_end_beats, 16.0);
        assert!(!app.data.transport.cycle, "locators alone do not loop");
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Set Locators");

        app.loop_selection();
        assert!(app.data.transport.cycle);
        assert!(app.status_message.contains("Looping the selection"));

        app.play_selection_range();
        assert!(app.data.transport.cycle);
        assert!(app.status_message.contains("Playing the selection range"));
    }

    #[test]
    fn pre_roll_uses_both_selection_edges_and_writes_no_history() {
        let mut app = app_with_events();
        let first = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([first]);
        app.roll_lengths.pre_beats = 2.0;
        let history_before = app.project_history.counts();

        assert!(app.schedule_roll(false, false), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 2.0);
        assert_eq!(app.play_until, Some(4.0));
        app.set_transport_playing(false);

        assert!(app.schedule_roll(false, true), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 6.0);
        assert_eq!(app.play_until, Some(8.0));
        app.set_transport_playing(false);

        assert_eq!(
            app.project_history.counts(),
            history_before,
            "roll scheduling must not create an undo step"
        );

        // A near-zero target clamps at the project start and still plays.
        let near_start = app
            .data
            .project
            .add_audio_clip(0, PathBuf::from("c.wav"), 0.5, 0.25)
            .expect("clip");
        app.arrange_view_state
            .audio_events
            .select_many([near_start]);
        assert!(app.schedule_roll(false, false), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 0.0);
        assert_eq!(app.play_until, Some(0.5));
        app.set_transport_playing(false);
    }

    #[test]
    fn pre_roll_refuses_a_selection_at_the_project_start() {
        let mut app = app_with_events();
        let at_zero = app
            .data
            .project
            .add_audio_clip(0, PathBuf::from("zero.wav"), 0.0, 0.5)
            .expect("clip");
        app.arrange_view_state.audio_events.select_many([at_zero]);
        assert!(!app.schedule_roll(false, false));
        assert!(app.status_message.contains("no room to pre-roll"));
        assert!(!app.data.transport.playing);
    }

    #[test]
    fn post_roll_uses_both_edges_with_independent_lengths_and_no_history() {
        let mut app = app_with_events();
        let first = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([first]);
        app.roll_lengths.pre_beats = 1.0;
        app.roll_lengths.post_beats = 6.0;
        let history_before = app.project_history.counts();

        assert!(app.schedule_roll(true, false), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 4.0);
        assert_eq!(app.play_until, Some(10.0));
        app.set_transport_playing(false);

        assert!(app.schedule_roll(true, true), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 8.0);
        assert_eq!(app.play_until, Some(14.0));
        app.set_transport_playing(false);

        assert_eq!(app.project_history.counts(), history_before);

        // A selection near the end of the project still gets its full tail;
        // the transport plays the silence after the last event.
        let late = app
            .data
            .project
            .add_audio_clip(0, PathBuf::from("late.wav"), 100.0, 1.0)
            .expect("clip");
        app.arrange_view_state.audio_events.select_many([late]);
        assert!(app.schedule_roll(true, false), "{}", app.status_message);
        assert_eq!(app.data.transport.position_beats, 100.0);
        assert_eq!(app.play_until, Some(106.0));
        app.set_transport_playing(false);
    }

    #[test]
    fn post_roll_interruption_clears_the_target() {
        let mut app = app_with_events();
        let first = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([first]);
        assert!(app.schedule_roll(true, false));
        assert!(app.play_until.is_some());
        app.set_transport_playing(false);
        assert_eq!(app.play_until, None);
        app.seek_to_beats(1.0);
        assert_eq!(app.play_until, None);
    }

    #[test]
    fn midi_reset_uses_the_live_destination_when_one_is_open() {
        let mut app = app_with_events();
        let Some(_) = app.audio_engine.as_ref() else {
            return;
        };
        app.virtual_keyboard_held.insert(60);
        app.virtual_keyboard_held.insert(67);
        let before = app.data.project.clone();
        app.reset_midi_destination();
        assert!(app.virtual_keyboard_held.is_empty());
        assert!(
            app.status_message.contains("16 channels")
                || app.status_message.contains("queue was full"),
            "{}",
            app.status_message
        );
        assert_eq!(app.data.project, before);
    }

    #[test]
    fn the_transport_menu_and_shortcut_share_the_selection_range_command() {
        let ctx = egui::Context::default();
        let ids_for = |app: &OpenTrackApp| {
            [
                app.data.project.tracks[0].clips[0].id,
                app.data.project.tracks[0].clips[1].id,
            ]
        };
        let mut via_menu = app_with_events();
        let ids = ids_for(&via_menu);
        via_menu.arrange_view_state.audio_events.select_many(ids);
        via_menu.run_transport_locate(TransportLocate::PlaySelection);

        let mut via_key = app_with_events();
        let ids = ids_for(&via_key);
        via_key.arrange_view_state.audio_events.select_many(ids);
        via_key.dispatch_reference_command(
            "transport.play_selection_range",
            "Play Selection Range",
            opentrack_core::commands::KeyChord::new(
                opentrack_core::commands::KeyCode::Space,
                opentrack_core::commands::KeyModifiers {
                    alt: true,
                    ..Default::default()
                },
            ),
            &ctx,
        );

        assert_eq!(
            via_menu.data.project.loop_start_beats,
            via_key.data.project.loop_start_beats
        );
        assert_eq!(
            via_menu.data.project.loop_end_beats,
            via_key.data.project.loop_end_beats
        );
        assert!(via_key.data.transport.cycle);
        assert_eq!(via_menu.status_message, via_key.status_message);
    }

    #[test]
    fn roll_scheduling_refuses_unsupported_state_and_cancels_on_seek() {
        let mut app = app_with_events();
        app.arrange_view_state.audio_events.clear_selection();
        app.data.project.selected_midi_part_id = None;
        assert!(!app.schedule_roll(false, false));
        assert!(app.status_message.contains("Select an audio event"));

        let id = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([id]);
        app.data.transport.cycle = true;
        assert!(!app.schedule_roll(false, false));
        assert!(app.status_message.contains("Turn off Cycle"));
        app.data.transport.cycle = false;

        app.roll_lengths.pre_beats = 0.0;
        assert!(!app.schedule_roll(false, false));
        assert!(app.status_message.contains("length is zero"));
        app.roll_lengths = crate::transport_commands::RollLengths::default();

        // The fixture has an engine, so a valid roll schedules and starts.
        assert!(app.schedule_roll(true, false), "{}", app.status_message);
        assert!(app.play_until.is_some());
        assert!(app.status_message.contains("Post-roll"));
        assert!(app.status_message.contains("stopping at beat"));
        app.set_transport_playing(false);
        assert_eq!(app.play_until, None, "stopping clears the roll target");

        // A manual seek clears an existing scheduled target.
        app.play_until = Some(99.0);
        app.seek_to_beats(3.0);
        assert_eq!(app.play_until, None);
        assert_eq!(app.data.transport.position_beats, 3.0);
    }

    #[test]
    fn a_scheduled_roll_stops_on_the_first_check_at_or_after_its_target() {
        let mut app = app_with_events();
        let id = app.data.project.tracks[0].clips[0].id;
        app.arrange_view_state.audio_events.select_many([id]);
        app.data.transport.playing = true;
        app.play_until = Some(10.0);
        app.data.transport.position_beats = 9.999;
        app.advance_play_until();
        assert!(
            app.data.transport.playing,
            "a position inside the block before the target keeps playing"
        );
        app.data.transport.position_beats = 10.0;
        app.advance_play_until();
        assert!(!app.data.transport.playing);
        assert_eq!(app.play_until, None);
        assert!(app.status_message.contains("stopped at beat 10.000"));
    }

    #[test]
    fn the_commands_refuse_without_a_selection() {
        let mut app = app_with_events();
        app.arrange_view_state.audio_events.clear_selection();
        app.data.project.selected_midi_part_id = None;
        let before = app.data.project.clone();
        app.locators_to_selection();
        assert!(app.status_message.contains("Select an event"));
        app.loop_selection();
        assert!(app.status_message.contains("Select an event"));
        app.play_selection_range();
        assert!(app.status_message.contains("Select an event"));
        assert_eq!(app.data.project, before);
        assert!(!app.data.transport.cycle);
    }

    #[test]
    fn folding_every_group_is_one_labelled_undo_step() {
        let mut app = app_with_events();
        app.data.project.add_track(TrackKind::Group);
        app.data.project.add_track(TrackKind::Group);
        app.project_history.clear();

        app.set_all_groups_collapsed(true);
        assert!(
            app.data
                .project
                .tracks
                .iter()
                .filter(|track| track.kind == TrackKind::Group)
                .all(|track| track.group_collapsed)
        );
        assert!(app.status_message.contains("Collapsed 2 group track(s)"));
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Fold Groups");

        app.set_all_groups_collapsed(true);
        assert!(app.status_message.contains("already collapsed"));

        app.set_all_groups_collapsed(false);
        assert!(
            app.data
                .project
                .tracks
                .iter()
                .filter(|track| track.kind == TrackKind::Group)
                .all(|track| !track.group_collapsed)
        );
        assert!(app.status_message.contains("Expanded 2 group track(s)"));
    }
}

#[cfg(test)]
mod inspector_panel_tests {
    use super::*;

    #[test]
    fn the_show_panel_menu_entry_and_command_share_one_toggle() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx.clone());
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        assert!(app.arrange_view_state.show_inspector, "shown by default");

        // The Window > Show Panel entry's action.
        app.toggle_inspector_panel();
        assert!(!app.arrange_view_state.show_inspector);
        assert_eq!(app.status_message, "Inspector panel hidden");

        // The keymap command flips the same flag, with the same status text.
        app.dispatch_reference_command(
            "editors.show_hide_inspector",
            "Show/Hide Inspector",
            KeyChord::new(
                KeyCode::Letter('I'),
                KeyModifiers {
                    alt: true,
                    ..KeyModifiers::default()
                },
            ),
            &ctx,
        );
        assert!(app.arrange_view_state.show_inspector);
        assert_eq!(app.status_message, "Inspector panel shown");

        // The flag is persisted view state, and older files show the panel.
        let encoded = serde_json::to_string(&app.arrange_view_state).expect("encode");
        let restored: ArrangeViewState = serde_json::from_str(&encoded).expect("decode");
        assert!(restored.show_inspector);
        let mut legacy: serde_json::Value = serde_json::from_str(&encoded).expect("value");
        legacy
            .as_object_mut()
            .expect("object")
            .remove("show_inspector");
        let legacy: ArrangeViewState = serde_json::from_value(legacy).expect("legacy");
        assert!(legacy.show_inspector, "legacy projects keep the panel");
    }
}

#[cfg(test)]
mod transport_readout_tests {
    use super::*;

    #[test]
    fn the_readout_names_capacity_position_and_remaining_separately() {
        // Both displays off keeps the recording summary only.
        assert_eq!(
            recording_readout_line(
                "48000 Hz",
                "24 Bit PCM",
                Some(8 * 3600 + 45 * 60),
                3.5,
                false,
                false
            ),
            "Rec: 48000 Hz - 24 Bit PCM - Max: 008h 45m"
        );

        // Time is the transport position in H:MM:SS.mmm.
        let with_time =
            recording_readout_line("48000 Hz", "24 Bit PCM", Some(4 * 3600), 3.5, true, false);
        assert!(with_time.ends_with(" - Time: 0:00:03.500"), "{with_time}");

        // Remaining counts down from the cursor, not from zero.
        let with_remaining =
            recording_readout_line("48000 Hz", "24 Bit PCM", Some(4 * 3600), 600.0, false, true);
        assert!(
            with_remaining.ends_with(" - Rem: 003h 50m"),
            "{with_remaining}"
        );

        // Both segments can be shown together.
        let both =
            recording_readout_line("48000 Hz", "32 Bit Float", Some(3_600), 120.0, true, true);
        assert!(both.contains("- Time: 0:02:00.000"), "{both}");
        assert!(both.contains("- Rem: 000h 58m"), "{both}");

        // Past the capacity there is no negative remaining time.
        let past = recording_readout_line("48000 Hz", "24 Bit PCM", Some(60), 120.0, false, true);
        assert!(past.ends_with(" - Rem: 000h 00m"), "{past}");

        // No usable recording folder reports instead of guessing.
        let unavailable = recording_readout_line("48000 Hz", "24 Bit PCM", None, 0.0, true, true);
        assert!(unavailable.contains("Max: unavailable"), "{unavailable}");
        assert!(unavailable.contains("Rem: unavailable"), "{unavailable}");
    }

    #[test]
    fn the_display_toggles_change_the_readout_the_user_sees() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.data.transport.position_beats = 4.0;
        assert!(!app.arrange_view_state.show_time_display);
        assert!(!app.arrange_view_state.show_remaining_record_time);

        let plain = recording_readout_line(
            "48000 Hz",
            "24 Bit PCM",
            Some(600),
            2.0,
            app.arrange_view_state.show_time_display,
            app.arrange_view_state.show_remaining_record_time,
        );
        assert!(!plain.contains("Time:"), "{plain}");

        app.toggle_time_display();
        assert!(app.arrange_view_state.show_time_display);
        assert!(app.status_message.contains("Time display shown"));
        let with_time = recording_readout_line(
            "48000 Hz",
            "24 Bit PCM",
            Some(600),
            2.0,
            app.arrange_view_state.show_time_display,
            app.arrange_view_state.show_remaining_record_time,
        );
        assert!(with_time.contains("Time: 0:00:02.000"), "{with_time}");

        app.toggle_remaining_record_time_display();
        assert!(app.arrange_view_state.show_remaining_record_time);
        assert!(app.status_message.contains("Remaining record time shown"));

        // Turning each back off restores the shorter line.
        app.toggle_time_display();
        app.toggle_remaining_record_time_display();
        assert!(app.status_message.contains("Remaining record time hidden"));
        let plain_again = recording_readout_line(
            "48000 Hz",
            "24 Bit PCM",
            Some(600),
            2.0,
            app.arrange_view_state.show_time_display,
            app.arrange_view_state.show_remaining_record_time,
        );
        assert_eq!(plain, plain_again);
    }
}

#[cfg(test)]
mod automation_panel_tests {
    use super::*;
    use opentrack_core::automation::{AutomationLane, AutomationPoint, AutomationTarget};

    fn app_with_lane() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.tracks[0].name = "Vocal".to_owned();
        app.data.project.tracks[0]
            .automation_lanes
            .push(AutomationLane {
                target: AutomationTarget::TrackVolume,
                points: vec![
                    AutomationPoint {
                        beat: 1.0,
                        value: 0.5,
                    },
                    AutomationPoint {
                        beat: 3.0,
                        value: 0.8,
                    },
                ],
            });
        app.data.project.selected_track = Some(0);
        app
    }

    fn run(ctx: &egui::Context, app: &mut OpenTrackApp, frame: usize) -> Vec<String> {
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(900.0, 700.0))),
                time: Some(frame as f64 * 0.05),
                ..Default::default()
            },
            |_| app.show_automation_panel(ctx),
        );
        output.textures_delta.clear();
        let mut texts = Vec::new();
        fn walk(shape: &egui::Shape, texts: &mut Vec<String>) {
            match shape {
                egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                egui::Shape::Vec(shapes) => {
                    for shape in shapes {
                        walk(shape, texts);
                    }
                }
                _ => {}
            }
        }
        for shape in &output.shapes {
            walk(&shape.shape, &mut texts);
        }
        texts
    }

    #[test]
    fn the_panel_lists_lanes_and_toggles_their_visibility() {
        let ctx = egui::Context::default();
        let mut app = app_with_lane();
        app.automation_panel_open = true;
        let track_id = app.data.project.tracks[0].id;

        // The toggle is the same state the arrange reads.
        assert!(app.toggle_automation_lane_visibility(track_id));
        assert!(
            app.arrange_view_state
                .automation_visible
                .contains(&track_id)
        );
        assert!(!app.toggle_automation_lane_visibility(track_id));
        assert!(
            !app.arrange_view_state
                .automation_visible
                .contains(&track_id)
        );

        run(&ctx, &mut app, 0);
        let texts = run(&ctx, &mut app, 1);
        let joined = texts.join("\n");
        assert!(joined.contains("Automation Panel"), "{joined}");
        assert!(joined.contains("Vocal"), "{joined}");
        assert!(joined.contains("Volume: 2 point(s)"), "{joined}");
        assert!(joined.contains("Show in Arrange"), "{joined}");
    }

    #[test]
    fn an_empty_project_says_there_are_no_lanes() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx.clone());
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.automation_panel_open = true;
        run(&ctx, &mut app, 0);
        let texts = run(&ctx, &mut app, 1);
        assert!(
            texts
                .iter()
                .any(|text| text.contains("No track has an automation lane")),
            "{texts:?}"
        );
    }
}

#[cfg(test)]
mod timecode_tests {
    use super::*;

    fn app() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.tempo_bpm = 120.0;
        app.project_history.clear();
        app
    }

    #[test]
    fn setting_the_timecode_is_one_labelled_undo_step() {
        let mut app = app();
        app.data.transport.position_beats = 2.0;
        app.open_timecode_dialog();
        // One second at 120 BPM is two beats, so the dialog seeds 1.0.
        assert_eq!(app.timecode_dialog, Some(1.0));

        app.apply_timecode_at_cursor(3600.0);
        assert!((app.data.project.timecode_offset_seconds - 3599.0).abs() < 1e-9);
        assert!(app.status_message.contains("01:00:00:00"));
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Set Timecode");

        // Refusals: same value, negative, and out of range.
        let steps = app.project_history.counts().0;
        app.apply_timecode_at_cursor(3600.0);
        assert!(app.status_message.contains("already that value"));
        app.apply_timecode_at_cursor(-1.0);
        assert!(app.status_message.contains("non-negative"));
        app.apply_timecode_at_cursor(1_000_000.0);
        assert!(app.status_message.contains("outside the supported range"));
        assert_eq!(app.project_history.counts().0, steps);
    }

    #[test]
    fn the_timecode_ruler_label_applies_the_project_offset() {
        // Timecode formats 2 and 4 carry the offset; bars and seconds do not.
        // Bar 2 is eight beats, which is four seconds at 120 BPM.
        assert_eq!(ruler_label(0, 2, 4, 120.0, 48_000, 3600.0), "01:00:00:00");
        assert_eq!(ruler_label(2, 2, 4, 120.0, 48_000, 3600.0), "01:00:04:00");
        assert_eq!(ruler_label(2, 4, 4, 120.0, 48_000, 0.0), "00:00:04:00");
        assert_eq!(ruler_label(2, 0, 4, 120.0, 48_000, 3600.0), "3");
        assert_eq!(ruler_label(2, 1, 4, 120.0, 48_000, 3600.0), "00:04");
    }
}

#[cfg(test)]
mod virtual_keyboard_tests {
    use super::*;

    fn app() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app
    }

    #[test]
    fn keys_map_to_note_messages_on_channel_one() {
        match virtual_keyboard_message(60, true) {
            MidiInputMessage::NoteOn {
                channel,
                key,
                velocity,
            } => {
                assert_eq!(channel, 0);
                assert_eq!(key, 60);
                assert_eq!(velocity, 100);
            }
            other => panic!("unexpected message {other:?}"),
        }
        match virtual_keyboard_message(60, false) {
            MidiInputMessage::NoteOff { channel, key, .. } => {
                assert_eq!(channel, 0);
                assert_eq!(key, 60);
            }
            other => panic!("unexpected message {other:?}"),
        }
        // Out-of-range keys are clamped rather than sent raw.
        match virtual_keyboard_message(200, true) {
            MidiInputMessage::NoteOn { key, .. } => assert_eq!(key, 127),
            other => panic!("unexpected message {other:?}"),
        }
    }

    #[test]
    fn midi_reset_clears_held_keys_without_touching_project_data() {
        let mut app = app();
        app.virtual_keyboard_held.insert(60);
        app.virtual_keyboard_held.insert(64);
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.tracks[0].midi_parts.clear();
        let before = app.data.project.clone();
        let history = app.project_history.counts();
        app.reset_midi_destination();
        assert!(app.virtual_keyboard_held.is_empty());
        assert!(
            app.status_message
                .contains("no audio output device is open"),
            "{}",
            app.status_message
        );
        assert_eq!(app.data.project, before);
        assert_eq!(app.project_history.counts(), history);
        // Repeated resets are safe and report again.
        app.reset_midi_destination();
        assert!(app.status_message.contains("MIDI Reset"));

        // Closing the project drops held-key state rather than carrying it into
        // the next project.
        app.virtual_keyboard_held.insert(72);
        app.close_project();
        assert!(app.virtual_keyboard_held.is_empty());
        app.reset_midi_destination();
        assert!(app.status_message.contains("MIDI Reset"));
    }

    #[test]
    fn the_keyboard_reports_why_it_cannot_be_heard_without_a_device() {
        let mut app = app();
        assert!(!app.virtual_keyboard_open);
        app.toggle_virtual_keyboard();
        assert!(app.virtual_keyboard_open);
        assert!(
            app.status_message
                .contains("no audio output device is open")
        );

        // A key press with no engine reports and holds nothing, so no stuck note.
        app.virtual_keyboard_note(60, true);
        assert!(app.status_message.contains("cannot be heard"));
        assert!(app.virtual_keyboard_held.is_empty());

        // Closing clears the flag and says so.
        app.toggle_virtual_keyboard();
        assert!(!app.virtual_keyboard_open);
        assert_eq!(app.status_message, "Virtual keyboard closed");

        // The shortcut reaches the same toggle.
        let ctx = egui::Context::default();
        app.dispatch_reference_command(
            "devices.virtual_keyboard",
            "Virtual Keyboard",
            KeyChord::new(
                KeyCode::Letter('K'),
                KeyModifiers {
                    alt: true,
                    ..KeyModifiers::default()
                },
            ),
            &ctx,
        );
        assert!(app.virtual_keyboard_open);
    }

    #[test]
    fn the_keyboard_window_draws_keys_and_its_octave_control() {
        let ctx = egui::Context::default();
        let mut app = app();
        app.virtual_keyboard_open = true;
        let mut texts = Vec::new();
        for frame in 0..2 {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1000.0, 700.0))),
                    time: Some(frame as f64 * 0.05),
                    ..Default::default()
                },
                |_| app.show_virtual_keyboard(&ctx),
            );
            output.textures_delta.clear();
            if frame == 0 {
                continue;
            }
            fn walk(shape: &egui::Shape, texts: &mut Vec<String>) {
                match shape {
                    egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                    egui::Shape::Vec(shapes) => {
                        for shape in shapes {
                            walk(shape, texts);
                        }
                    }
                    _ => {}
                }
            }
            for shape in &output.shapes {
                walk(&shape.shape, &mut texts);
            }
        }
        let joined = texts.join("\n");
        assert!(joined.contains("Virtual Keyboard"), "{joined}");
        assert!(joined.contains("Octave"), "{joined}");
        assert!(
            joined.contains("Arm a MIDI or Instrument track"),
            "{joined}"
        );
        // The base octave starts at 3.
        assert!(joined.contains("3"), "{joined}");
    }
}

#[cfg(test)]
mod extra_mixer_persistence_tests {
    use super::*;

    #[test]
    fn the_extra_mixers_round_trip_through_the_workspace_snapshot() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        let second = WindowBounds {
            left: 120.0,
            top: 90.0,
            width: 820.0,
            height: 460.0,
            inner_width: None,
            inner_height: None,
            monitor_id: None,
        };
        let third = WindowBounds {
            left: 960.0,
            top: 120.0,
            width: 700.0,
            height: 400.0,
            inner_width: None,
            inner_height: None,
            monitor_id: None,
        };
        app.mixer_window_2.open = true;
        app.mixer_window_2.bounds = Some(second.clone());
        app.mixer_window_3.open = true;
        app.mixer_window_3.bounds = Some(third.clone());

        // Saving captures both extra mixers in the active workspace.
        let workspace_state = app.workspace_state_for_save().expect("workspace");
        let active = workspace_state.active_index.expect("active");
        let workspace = workspace_state.workspaces[active].clone();
        assert_eq!(
            main_window_window_snapshot(&workspace).is_some(),
            true,
            "the workspace still stores its main window"
        );

        // Restoring maps each mixer back to its own state.
        let restored_2 = restore_native_window_state(Some(&workspace), MIXER_2_WINDOW_ID, 0);
        let restored_3 = restore_native_window_state(Some(&workspace), MIXER_3_WINDOW_ID, 0);
        assert!(restored_2.open && restored_3.open);
        assert_eq!(restored_2.bounds, Some(second));
        assert_eq!(restored_3.bounds, Some(third));

        // Closing one is saved as closed without disturbing the other.
        app.mixer_window_2.open = false;
        let workspace_state = app.workspace_state_for_save().expect("workspace");
        let active = workspace_state.active_index.expect("active");
        let workspace = workspace_state.workspaces[active].clone();
        let restored_2 = restore_native_window_state(Some(&workspace), MIXER_2_WINDOW_ID, 0);
        let restored_3 = restore_native_window_state(Some(&workspace), MIXER_3_WINDOW_ID, 0);
        assert!(!restored_2.open);
        assert!(restored_3.open);
        assert_eq!(restored_3.bounds, app.mixer_window_3.bounds);
    }
}

#[cfg(test)]
mod extra_mixer_tests {
    use super::*;

    fn run(ctx: &egui::Context, app: &mut OpenTrackApp, slot: u8, frame: usize) -> Vec<String> {
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1400.0, 900.0))),
                time: Some(frame as f64 * 0.05),
                ..Default::default()
            },
            |_| app.show_extra_mixer(ctx, slot),
        );
        output.textures_delta.clear();
        let mut texts = Vec::new();
        fn walk(shape: &egui::Shape, texts: &mut Vec<String>) {
            match shape {
                egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                egui::Shape::Vec(shapes) => {
                    for shape in shapes {
                        walk(shape, texts);
                    }
                }
                _ => {}
            }
        }
        for shape in &output.shapes {
            walk(&shape.shape, &mut texts);
        }
        texts
    }

    fn app_with_tracks() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.add_track(TrackKind::Audio);
        app.data.project.add_track(TrackKind::Midi);
        app
    }

    #[test]
    fn the_extra_mixers_open_independently_of_the_docked_one() {
        let ctx = egui::Context::default();
        let mut app = app_with_tracks();
        assert!(!app.mixer_window_2.open);
        assert!(!app.mixer_window_3.open);

        // Neither extra mixer draws while closed.
        let closed = run(&ctx, &mut app, 1, 0);
        assert!(!closed.iter().any(|text| text == "Mixer 2"), "{closed:?}");

        let docked_before = app.mixer_window.open;
        app.mixer_window_2.open = true;
        run(&ctx, &mut app, 1, 1);
        let texts = run(&ctx, &mut app, 1, 2);
        let joined = texts.join("\n");
        assert!(joined.contains("Mixer 2"), "{joined}");
        // The mixer body is real, not a placeholder: the bus strips are drawn.
        assert!(
            joined.contains("Input 1/2") || joined.contains("stereo"),
            "{joined}"
        );
        assert!(app.mixer_window_2.open, "the window keeps its own state");
        assert_eq!(
            app.mixer_window.open, docked_before,
            "opening an extra mixer leaves the docked mixer alone"
        );

        // The third mixer is separate again.
        app.mixer_window_3.open = true;
        run(&ctx, &mut app, 2, 3);
        let texts = run(&ctx, &mut app, 2, 4);
        assert!(texts.iter().any(|text| text == "Mixer 3"), "{texts:?}");
        assert!(app.mixer_window_3.open);

        // Closing one leaves the other open.
        app.mixer_window_2.open = false;
        let texts = run(&ctx, &mut app, 2, 5);
        assert!(texts.iter().any(|text| text == "Mixer 3"));
        assert!(!app.mixer_window_2.open && app.mixer_window_3.open);
    }
}

#[cfg(test)]
mod spectrum_window_tests {
    use super::*;

    fn run(ctx: &egui::Context, app: &mut OpenTrackApp, frame: usize) -> Vec<String> {
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1100.0, 800.0))),
                time: Some(frame as f64 * 0.05),
                ..Default::default()
            },
            |_| {
                app.update_spectrum_analyzer();
                app.show_spectrum_window(ctx);
            },
        );
        output.textures_delta.clear();
        let mut texts = Vec::new();
        fn walk(shape: &egui::Shape, texts: &mut Vec<String>) {
            match shape {
                egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                egui::Shape::Vec(shapes) => {
                    for shape in shapes {
                        walk(shape, texts);
                    }
                }
                _ => {}
            }
        }
        for shape in &output.shapes {
            walk(&shape.shape, &mut texts);
        }
        texts
    }

    #[test]
    fn the_spectrum_window_draws_and_says_when_there_is_no_signal_source() {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx.clone());
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.spectrum_open = true;

        // The update has no device to tap and must stay calm about it.
        app.update_spectrum_analyzer();
        run(&ctx, &mut app, 0);
        let texts = run(&ctx, &mut app, 1);
        let joined = texts.join("\n");
        assert!(joined.contains("Spectrum Analyzer"), "{joined}");
        assert!(
            joined.contains("No audio output device is open"),
            "{joined}"
        );
        // The analyser's own controls are drawn, not a placeholder.
        assert!(
            joined.to_lowercase().contains("spectrum") || joined.contains("Hold"),
            "{joined}"
        );
        assert!(app.spectrum_open, "the window stays open");

        // Closing stops the analyser work and the window.
        app.spectrum_open = false;
        app.update_spectrum_analyzer();
        let texts = run(&ctx, &mut app, 2);
        assert!(
            !texts.iter().any(|text| text == "Spectrum Analyzer"),
            "{texts:?}"
        );
    }
}

#[cfg(test)]
mod list_editor_tests {
    use super::*;
    use opentrack_core::project::{MidiNote, MidiPart};

    fn app_with_notes() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.add_track(TrackKind::Midi);
        app.data.project.next_midi_part_id = 2;
        app.data.project.next_midi_note_id = 4;
        app.data.project.tracks[0].midi_parts.push(MidiPart {
            id: 1,
            name: "Lead".to_owned(),
            start_beats: 4.0,
            duration_beats: 8.0,
            notes: vec![
                MidiNote {
                    id: 1,
                    start_beats: 1.5,
                    duration_beats: 0.5,
                    pitch: 67,
                    channel: 0,
                    velocity: 90,
                },
                MidiNote {
                    id: 2,
                    start_beats: 0.0,
                    duration_beats: 1.0,
                    pitch: 60,
                    channel: 1,
                    velocity: 100,
                },
            ],
            controller_events: Vec::new(),
        });
        app.data.project.selected_midi_part_id = Some(1);
        app.project_history.clear();
        app
    }

    fn run(ctx: &egui::Context, app: &mut OpenTrackApp, frame: usize) -> Vec<String> {
        let mut output = ctx.run_ui(
            egui::RawInput {
                screen_rect: Some(Rect::from_min_size(Pos2::ZERO, Vec2::new(1000.0, 700.0))),
                time: Some(frame as f64 * 0.05),
                ..Default::default()
            },
            |_| app.show_list_editor(ctx),
        );
        output.textures_delta.clear();
        let mut texts = Vec::new();
        fn walk(shape: &egui::Shape, texts: &mut Vec<String>) {
            match shape {
                egui::Shape::Text(text) => texts.push(text.galley.text().to_owned()),
                egui::Shape::Vec(shapes) => {
                    for shape in shapes {
                        walk(shape, texts);
                    }
                }
                _ => {}
            }
        }
        for shape in &output.shapes {
            walk(&shape.shape, &mut texts);
        }
        texts
    }

    #[test]
    fn the_list_editor_shows_each_event_in_start_order() {
        let ctx = egui::Context::default();
        let mut app = app_with_notes();
        app.list_editor_open = true;
        run(&ctx, &mut app, 0);
        let texts = run(&ctx, &mut app, 1);
        let joined = texts.join("\n");
        assert!(joined.contains("List Editor"), "{joined}");
        assert!(joined.contains("Lead — 2 event(s)"), "{joined}");
        assert!(
            joined.contains("Start") && joined.contains("Velocity"),
            "{joined}"
        );
        assert!(joined.contains("C4"), "pitch name: {joined}");
        assert!(joined.contains("G4"), "pitch name: {joined}");
        assert!(joined.contains("1.500"), "{joined}");
        // The notes are listed by start time, so the C4 row comes first.
        let c4 = joined.find("C4").expect("C4 row");
        let g4 = joined.find("G4").expect("G4 row");
        assert!(c4 < g4, "start order: {joined}");

        // Without a selected part the window says so instead of guessing.
        app.data.project.selected_midi_part_id = None;
        run(&ctx, &mut app, 2);
        let texts = run(&ctx, &mut app, 3);
        assert!(
            texts
                .iter()
                .any(|text| text.contains("Select a MIDI part to list its events"))
        );
    }

    #[test]
    fn deleting_notes_from_the_list_editor_is_one_labelled_undo_step() {
        let mut app = app_with_notes();
        app.selected_midi_note_ids.insert(2);
        app.delete_selected_midi_notes();
        let part = &app.data.project.tracks[0].midi_parts[0];
        assert_eq!(part.notes.len(), 1);
        assert_eq!(part.notes[0].id, 1);
        assert!(app.status_message.contains("Removed 1 MIDI note(s)"));
        assert!(app.selected_midi_note_ids.is_empty());
        assert_eq!(app.project_history.steps()[0].label, "Delete Notes");

        // Empty selection and a missing part report without editing.
        let steps = app.project_history.counts().0;
        app.delete_selected_midi_notes();
        assert!(app.status_message.contains("Select MIDI notes to delete"));
        app.selected_midi_note_ids.insert(1);
        app.data.project.selected_midi_part_id = None;
        app.delete_selected_midi_notes();
        assert!(app.status_message.contains("Select a MIDI part"));
        assert_eq!(app.project_history.counts().0, steps);
        assert_eq!(app.data.project.tracks[0].midi_parts[0].notes.len(), 1);
    }
}

#[cfg(test)]
mod explode_channel_tests {
    use super::*;
    use opentrack_core::project::{MidiNote, MidiPart};

    fn app_with_part() -> OpenTrackApp {
        let ctx = egui::Context::default();
        let creation = eframe::CreationContext::_new_kittest(ctx);
        let mut app = OpenTrackApp::new_internal(&creation, false);
        app.project_open = true;
        app.data.project.add_track(TrackKind::Midi);
        app.data.project.next_midi_part_id = 2;
        app.data.project.next_midi_note_id = 4;
        app.data.project.tracks[0].midi_parts.push(MidiPart {
            id: 1,
            name: "Multi".to_owned(),
            start_beats: 0.0,
            duration_beats: 8.0,
            notes: vec![
                MidiNote {
                    id: 1,
                    start_beats: 0.0,
                    duration_beats: 1.0,
                    pitch: 60,
                    channel: 0,
                    velocity: 100,
                },
                MidiNote {
                    id: 2,
                    start_beats: 1.0,
                    duration_beats: 1.0,
                    pitch: 64,
                    channel: 3,
                    velocity: 100,
                },
            ],
            controller_events: Vec::new(),
        });
        app.data.project.selected_track = Some(0);
        app.data.project.selected_midi_part_id = Some(1);
        app.project_history.clear();
        app
    }

    #[test]
    fn exploding_by_channel_makes_one_track_per_channel_as_one_undo_step() {
        let mut app = app_with_part();
        app.explode_selected_midi_part(false);
        assert_eq!(app.data.project.tracks.len(), 3, "the source plus two");
        assert!(app.data.project.tracks[0].midi_parts.is_empty());
        let channels = app
            .data
            .project
            .tracks
            .iter()
            .flat_map(|track| track.midi_parts.iter())
            .flat_map(|part| part.notes.iter())
            .map(|note| note.channel)
            .collect::<Vec<_>>();
        assert_eq!(channels, vec![0, 3]);
        assert!(app.status_message.contains("2 channel track(s)"));
        assert_eq!(app.data.project.selected_track, Some(1));
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Explode");

        // The pitch variant keeps its own label and wording.
        let mut app = app_with_part();
        app.explode_selected_midi_part(true);
        assert!(app.status_message.contains("2 pitch track(s)"));
        app.project_history.finish_frame(&app.data.project, true);
        assert_eq!(app.project_history.steps()[0].label, "Explode Pitches");
    }
}

